INSERT INTO categories (id, name, description) VALUES ('current-affairs-gk', 'Current Affairs & General Knowledge', 'Static and current general knowledge spanning schemes, awards, sports, and national/international affairs — a cross-cutting GK category useful alongside any other exam.');

INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('current-affairs-gk-bank', NULL, 'Current Affairs & GK Prep', 'gk', 'shared', '2026-11-14T06:17:56.365Z', '2026-11-14T06:17:56.365Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('current-affairs-gk-bank', 'current-affairs-gk');

INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00001', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 0, 'What is the national bird of India?', 'The **national bird of India** is the **Indian Peacock** (*Pavo cristatus*).

It was given this status in **1963** because of its close association with Indian art, mythology, and culture.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00002', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 1, 'What is the national animal of India?', 'The **national animal of India** is the **Royal Bengal Tiger** (*Panthera tigris*).

It replaced the lion as the national animal in **1973**, the same year the **Project Tiger** conservation programme was launched.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00003', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 2, 'What is the national aquatic animal of India?', 'The **national aquatic animal of India** is the **Ganges River Dolphin** (*Platanista gangetica*), also called *Susu*.

It was declared so in **2009** and is also the state aquatic animal of several Gangetic-basin states.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00004', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 3, 'What is the national flower of India?', 'The **national flower of India** is the **Lotus** (*Nelumbo nucifera*).

It holds deep significance in **Indian culture and spirituality**, symbolizing purity, prosperity, and fertility.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00005', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 4, 'What is the national tree of India?', 'The **national tree of India** is the **Banyan Tree** (*Ficus benghalensis*).

It is noted for its **expansive canopy and longevity**, and is traditionally regarded as a symbol of immortality in Indian tradition.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00006', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 5, 'What is the national fruit of India?', 'The **national fruit of India** is the **Mango** (*Mangifera indica*).

India is one of the **largest producers of mangoes** in the world, and the fruit holds cultural significance going back thousands of years.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00007', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 6, 'What is the national heritage animal of India?', 'The **national heritage animal of India** is the **Indian Elephant** (*Elephas maximus indicus*), a status given in **2010** by the Ministry of Environment and Forests.

This designation aims to boost conservation efforts for the species.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00008', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 7, 'Which river is regarded as the National River of India?', 'The **Ganga (Ganges)** was declared the **National River of India** in **November 2008** by the National Ganga River Basin Authority (NGRBA).

It is the **longest river in India** and holds immense religious and cultural importance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00009', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 8, 'What is the National Emblem of India and where is it derived from?', 'The **National Emblem of India** is an adaptation of the **Lion Capital of Ashoka**, originally erected at **Sarnath** around **250 BCE** by Emperor Ashoka.

It was adopted as the official emblem on **26 January 1950**, the same day the Constitution came into force, and features four lions, a *Dharma Chakra*, and the motto *Satyameva Jayate*.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00010', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 9, 'Who wrote India''s National Anthem and when was it adopted?', 'India''s National Anthem, **"Jana Gana Mana"**, was composed by **Rabindranath Tagore** and was formally adopted by the Constituent Assembly on **24 January 1950**.

It was originally written in **Bengali** and first publicly sung in **1911** at the Calcutta session of the Indian National Congress.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00011', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 10, 'Who wrote India''s National Song and from which work is it taken?', 'India''s National Song, **"Vande Mataram"**, was composed by **Bankim Chandra Chatterjee** and is taken from his **1882 novel** *Anandamath*.

It was given the status of National Song by the Constituent Assembly in **January 1950**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00012', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 11, 'What is the motto inscribed on the National Emblem of India, and where is it taken from?', 'The motto inscribed on the National Emblem is **"Satyameva Jayate"**, meaning **"Truth alone triumphs."**

It is taken from the **Mundaka Upanishad**, an ancient Hindu scripture.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00013', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 12, 'Does India have an officially declared national sport?', 'No — despite a common misconception, **India has no officially declared national sport**.

The Ministry of Youth Affairs and Sports has clarified in Parliament that **no sport, including hockey, has been notified as the national sport** of India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00014', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 13, 'What is the ratio of the width to length of the Indian National Flag?', 'The **National Flag of India** has a width-to-length ratio of **2:3**.

It consists of three horizontal bands — **saffron, white, and green** — with the **Ashoka Chakra** (a 24-spoke navy-blue wheel) at the centre of the white band.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00015', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 14, 'Who designed the Indian National Flag?', 'The basic design of the Indian National Flag was created by **Pingali Venkayya**, a freedom fighter from Andhra Pradesh.

The flag in its present form was adopted by the Constituent Assembly on **22 July 1947**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00016', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 15, 'How many spokes does the Ashoka Chakra on the National Flag have?', 'The **Ashoka Chakra** on the National Flag has **24 spokes**.

It is modeled on the wheel that appears on the abacus of the **Lion Capital of Ashoka** at Sarnath, and represents the eternal wheel of law (*Dharma Chakra*).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00017', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 16, 'What calendar is used as India''s National Calendar, and from when?', 'India''s **National Calendar** is based on the **Saka Era**, with **Chaitra** as its first month.

It was adopted from **22 March 1957**, alongside the Gregorian calendar, for official government purposes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00018', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 17, 'When did the Indian rupee get its official currency symbol, and who designed it?', 'The symbol for the **Indian Rupee (₹)** was officially adopted on **15 July 2010**.

It was designed by **D. Udaya Kumar**, an IIT Guwahati post-graduate, and is based on a blend of the Devanagari letter "र" and the Roman letter "R".', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00019', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 18, 'Who wrote "Gitanjali" and what recognition did it bring?', '**Gitanjali** was written by **Rabindranath Tagore**, a collection of poems originally in Bengali.

Its English translation won Tagore the **Nobel Prize in Literature in 1913**, making him the **first Asian** to receive a Nobel Prize.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00020', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 19, 'Who is regarded as the author of the "Ramayana"?', 'The **Ramayana** is traditionally attributed to the sage **Valmiki**, regarded as the **Adi Kavi** ("first poet") in Sanskrit literature.

It is one of the two major Sanskrit epics of ancient India, the other being the **Mahabharata**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00021', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 20, 'Who is credited with composing the "Mahabharata"?', 'The **Mahabharata** is traditionally attributed to the sage **Ved Vyasa**.

It is the **longest epic poem** known in world literature and includes the **Bhagavad Gita** as one of its sections.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00022', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 21, 'Who wrote the "Panchatantra" and what is it known for?', 'The **Panchatantra** was composed by **Vishnu Sharma**.

It is an ancient collection of **interrelated animal fables and moral stories**, originally composed in Sanskrit to impart lessons in statecraft and wise conduct.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00023', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 22, 'Who wrote the "Arthashastra" and what is it about?', 'The **Arthashastra** was written by **Kautilya**, also known as **Chanakya** or **Vishnugupta**.

It is an ancient treatise on **statecraft, economic policy, and military strategy**, composed around the **4th century BCE**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00024', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 23, 'Who wrote the autobiography "My Experiments with Truth"?', '**"My Experiments with Truth"** is the autobiography of **Mahatma Gandhi**.

It was originally written in **Gujarati** and later translated into English by Mahadev Desai.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00025', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 24, 'Who authored "The Discovery of India"?', '**"The Discovery of India"** was written by **Jawaharlal Nehru**, independent India''s first Prime Minister.

He wrote it during his imprisonment at **Ahmednagar Fort** between **1942 and 1946**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00026', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 25, 'Who wrote "India Wins Freedom"?', '**"India Wins Freedom"** was authored by **Maulana Abul Kalam Azad**, who served as the first Education Minister of independent India.

The book offers his account of the events leading up to India''s independence and partition.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00027', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 26, 'Who wrote the autobiography "Wings of Fire"?', '**"Wings of Fire"** is the autobiography of **Dr. A. P. J. Abdul Kalam**, co-authored with **Arun Tiwari**.

It traces his journey from a modest background to becoming a leading aerospace scientist and later the President of India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00028', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 27, 'Who wrote "Godan" and in which language?', '**"Godan"** was written by **Munshi Premchand** in **Hindi**.

It is considered one of the greatest works of modern Hindi literature, depicting the struggles of Indian peasantry.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00029', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 28, 'Who created the fictional town of "Malgudi" in Indian English literature?', 'The fictional town of **Malgudi** was created by author **R. K. Narayan**.

It serves as the setting for many of his acclaimed novels and short stories, including *Malgudi Days* and *Swami and Friends*.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00030', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 29, 'Who wrote "Midnight''s Children" and what award did it win?', '**"Midnight''s Children"** was written by **Salman Rushdie**, an Indian-born British author.

It won the **Booker Prize in 1981**, and was later also named the **"Booker of Bookers"** for being judged the best novel among all Booker Prize winners.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00031', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 30, 'Who wrote "The God of Small Things" and what award did it win?', '**"The God of Small Things"** was written by **Arundhati Roy**.

It won the **Booker Prize in 1997**, making Roy the first Indian woman to win the award.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00032', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 31, 'Who wrote "A Suitable Boy"?', '**"A Suitable Boy"** was written by **Vikram Seth**.

Published in **1993**, it is one of the longest novels ever published in the English language.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00033', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 32, 'Who composed Bangladesh''s national anthem, and what is notable about it?', 'Bangladesh''s national anthem, **"Amar Sonar Bangla,"** was composed by **Rabindranath Tagore**.

This makes Tagore the **only person to have written the national anthems of two countries** — India and Bangladesh.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00034', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 33, 'Who was the Chairman of the Drafting Committee of the Indian Constitution?', '**Dr. B. R. Ambedkar** served as the **Chairman of the Drafting Committee** of the Constituent Assembly.

He is widely regarded as the **"Father of the Indian Constitution"** for his pivotal role in its framing.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00035', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 34, 'Who was the President of the Constituent Assembly of India?', '**Dr. Rajendra Prasad** served as the **President of the Constituent Assembly**.

He went on to become the **first President of independent India**, serving from **1950 to 1962**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00036', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 35, 'On what date did the Constitution of India come into force?', 'The **Constitution of India** came into force on **26 January 1950**, which is celebrated every year as **Republic Day**.

The Constitution had been adopted by the Constituent Assembly earlier, on **26 November 1949**, a date now observed as **Constitution Day** (*Samvidhan Divas*).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00037', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 36, 'From which country did India borrow the concept of Fundamental Rights in its Constitution?', 'India borrowed the concept of **Fundamental Rights** from the **Constitution of the United States of America**.

These rights are enshrined in **Part III** of the Indian Constitution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00038', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 37, 'From which country did India borrow the concept of Directive Principles of State Policy?', 'India borrowed the concept of **Directive Principles of State Policy** from the **Constitution of Ireland**.

These are contained in **Part IV** of the Indian Constitution and serve as guidelines for governance, though they are not legally enforceable.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00039', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 38, 'From which country''s constitutional system did India adopt its parliamentary form of government?', 'India adopted its **parliamentary system of government** from the **United Kingdom**.

This includes features such as the **Cabinet system**, the concept of **collective responsibility**, and the office of a nominal head of state.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00040', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 39, 'Who was the first President of India?', '**Dr. Rajendra Prasad** was the **first President of India**, serving two terms from **1950 to 1962**.

He remains the only President to date to have served **two full terms** in office.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00041', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 40, 'Who was the first Prime Minister of India?', '**Jawaharlal Nehru** was the **first Prime Minister of India**, serving from **15 August 1947 until his death in 1964**.

He remains India''s **longest-serving Prime Minister**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00042', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 41, 'Who was independent India''s first Governor-General?', '**Lord Mountbatten** served as independent India''s first Governor-General, from **August 1947 to June 1948**.

He was succeeded by **C. Rajagopalachari**, who became the **first and only Indian to hold the office of Governor-General**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00043', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 42, 'Who was India''s first woman Prime Minister?', '**Indira Gandhi** became India''s **first woman Prime Minister**, first taking office in **1966**.

She remains the **only woman to have held the post** of Prime Minister of India to date.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00044', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 43, 'Who was India''s first woman President?', '**Pratibha Patil** became India''s **first woman President**, serving from **2007 to 2012**.

She was also the **first woman Governor of Rajasthan** before being elected President.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00045', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 44, 'Who was the first Indian astronaut to travel to space?', '**Rakesh Sharma** became the **first Indian to travel to space**, flying aboard the Soviet **Soyuz T-11** mission in **April 1984**.

He spent about **eight days** aboard the **Salyut 7** space station.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00046', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 45, 'What was India''s first satellite, and when was it launched?', 'India''s first satellite, **Aryabhata**, was launched on **19 April 1975** with assistance from the **Soviet Union**.

It was named after the ancient Indian mathematician and astronomer **Aryabhata**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00047', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 46, 'Who was the first woman from India to climb Mount Everest?', '**Bachendri Pal** became the **first Indian woman to climb Mount Everest**, achieving the feat on **23 May 1984**.

She was later awarded the **Padma Shri** for this accomplishment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00048', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 47, 'Where was the capital of British India before it was shifted to Delhi?', '**Calcutta (Kolkata)** served as the capital of British India before the capital was shifted.

The transfer to **Delhi** was announced at the **Delhi Durbar in 1911** and took effect in **1912**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00049', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 48, 'How many Fundamental Rights does the Indian Constitution currently guarantee?', 'The Indian Constitution currently guarantees **six Fundamental Rights**.

Originally there were **seven**, but the **Right to Property** was removed from the list of Fundamental Rights by the **44th Constitutional Amendment (1978)** and made a legal right under Article 300-A instead.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00050', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 49, 'Which words were added to the Preamble of the Indian Constitution by the 42nd Amendment?', 'The **42nd Constitutional Amendment (1976)** added the words **"Socialist," "Secular,"** and **"Integrity"** to the Preamble.

This amendment is sometimes referred to as a **"Mini-Constitution"** due to the scale of changes it introduced.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00051', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 50, 'How many states and Union Territories does India currently have?', 'India currently has **28 states** and **8 Union Territories**.

This configuration took shape after the **reorganisation of Jammu and Kashmir in 2019**, which created the Union Territories of **Jammu & Kashmir** and **Ladakh**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00052', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 51, 'Which is the largest state in India by area?', '**Rajasthan** is the **largest state in India by area**, covering roughly **3.42 lakh square kilometres**.

It is known for the **Thar Desert** and shares an international border with Pakistan.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00053', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 52, 'Which is the smallest state in India by area?', '**Goa** is the **smallest state in India by area**.

Despite its small size, it is known for its beaches, Portuguese colonial heritage, and status as a major tourist destination.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00054', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 53, 'Which Indian state has the highest number of UNESCO World Heritage Sites?', '**Maharashtra** has the **highest number of UNESCO World Heritage Sites** among Indian states, including the **Ajanta and Ellora Caves** and the **Elephanta Caves**.

UNESCO World Heritage status recognises sites of outstanding cultural or natural importance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00055', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 54, 'What was India''s first registered Geographical Indication (GI) tag product?', '**Darjeeling Tea** became India''s **first product to receive a Geographical Indication (GI) tag**, registered in **2004-05**.

A GI tag identifies a product as originating from a specific region and possessing qualities attributable to that origin.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00056', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 55, 'Who wrote "Hind Swaraj" and what does it discuss?', '**"Hind Swaraj"** was written by **Mahatma Gandhi** in **1909**, originally in Gujarati.

It outlines his critique of Western civilization and his vision of **self-rule (swaraj)** for India through non-violent means.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00057', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 56, 'Who founded the Arya Samaj, and which book did he author?', 'The **Arya Samaj** was founded by **Swami Dayananda Saraswati** in **1875**.

He authored **"Satyarth Prakash"** ("The Light of Truth"), which laid out his religious and social reform philosophy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00058', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 57, 'Which ancient Indian text is known as the oldest of the four Vedas?', 'The **Rigveda** is regarded as the **oldest of the four Vedas**, composed in Vedic Sanskrit.

The other three Vedas are the **Samaveda, Yajurveda, and Atharvaveda**, together forming the foundational texts of Hinduism.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00059', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 58, 'What is the significance of the Bhagavad Gita, and where does it appear?', 'The **Bhagavad Gita** is a **700-verse scripture** that appears within the **Bhishma Parva of the Mahabharata**.

It takes the form of a dialogue between **Lord Krishna and Arjuna** on the battlefield of Kurukshetra, addressing duty, righteousness, and the nature of the self.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00060', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 59, 'Who wrote "Anandamath," the novel containing "Vande Mataram"?', '**"Anandamath"** was written by **Bankim Chandra Chatterjee**, published in **1882**.

The novel is set against the backdrop of the **Sannyasi Rebellion** and contains the song "Vande Mataram," later adopted as India''s National Song.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00061', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 60, 'Who was the first Indian to win a Nobel Prize in a scientific field?', '**C. V. Raman** became the **first Indian to win a Nobel Prize in a scientific field**, receiving the **Nobel Prize in Physics in 1930**.

He was honoured for his discovery of the **"Raman Effect,"** related to the scattering of light.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00062', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 61, 'What is celebrated as "National Panchayati Raj Day" in India and why that date?', '**National Panchayati Raj Day** is observed on **24 April** every year.

The date marks the anniversary of the **73rd Constitutional Amendment Act** coming into force in **1993**, which gave constitutional status to Panchayati Raj institutions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00063', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 62, 'Which Indian city is known as the "Silicon Valley of India"?', '**Bengaluru** is popularly known as the **"Silicon Valley of India"**.

It earned this name due to its status as the country''s leading hub for **information technology and software companies**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00064', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 63, 'What is the significance of 15 August 1947 in Indian history?', '**15 August 1947** marks the day **India gained independence** from British colonial rule.

It is celebrated annually as **Independence Day**, with the Prime Minister hoisting the national flag at the **Red Fort** in Delhi.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00065', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 64, 'Who gave the famous "Tryst with Destiny" speech, and on what occasion?', '**Jawaharlal Nehru** delivered the famous **"Tryst with Destiny"** speech on the night of **14-15 August 1947**.

The speech marked India''s transition to independence and is considered one of the greatest speeches of the 20th century.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00066', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 65, 'What was the significance of the Dandi March led by Gandhi?', 'The **Dandi March**, led by **Mahatma Gandhi** in **1930**, was a act of civil disobedience against the British **salt tax**.

Gandhi walked about **390 kilometres** from Sabarmati Ashram to the coastal village of **Dandi** to make salt himself, symbolically defying British law.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00067', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 66, 'In which year was the Indian National Congress founded, and by whom?', 'The **Indian National Congress (INC)** was founded in **1885**.

It was established with the key involvement of **Allan Octavian Hume**, a retired British civil servant, along with Indian leaders of the time.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00068', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 67, 'What was the Jallianwala Bagh massacre and when did it occur?', 'The **Jallianwala Bagh massacre** occurred on **13 April 1919** in Amritsar, Punjab.

British troops under **General Reginald Dyer** opened fire on an unarmed gathering, killing hundreds of civilians, an event that significantly intensified India''s independence movement.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00069', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 68, 'Which movement did Gandhi launch in 1942, demanding an end to British rule?', 'Gandhi launched the **Quit India Movement** in **August 1942**, demanding an immediate end to British rule in India.

It is also known by the slogan **"Do or Die,"** given by Gandhi during this campaign.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00070', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 69, 'What does the term "Panchsheel" refer to in Indian history?', '**Panchsheel** refers to the **"Five Principles of Peaceful Coexistence"**, first formally enunciated in a **1954 agreement between India and China**.

The principles include mutual respect for sovereignty and non-interference in internal affairs.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00071', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 70, 'Who is known as the "Iron Man of India" and why?', '**Sardar Vallabhbhai Patel** is known as the **"Iron Man of India"**.

He earned this title for his decisive role in the **political integration of over 560 princely states** into the Indian Union after independence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00072', 'current-affairs-gk-bank', 'Static GK (Books, Authors, National Symbols)', 0, 71, 'What is the "Statue of Unity" and whom does it depict?', 'The **"Statue of Unity"**, located in Gujarat, is a statue depicting **Sardar Vallabhbhai Patel**.

Standing at about **182 metres**, it is recognised as the **tallest statue in the world**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00073', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 0, 'What is the Pradhan Mantri Jan Dhan Yojana (PMJDY) and when was it launched?', '**Pradhan Mantri Jan Dhan Yojana (PMJDY)** was launched on **28 August 2014** by the **Ministry of Finance** to promote **financial inclusion**.

Its main objective is to ensure **access to basic banking accounts, insurance, and credit** for every unbanked household in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00074', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 1, 'What is the Swachh Bharat Abhiyan and when was it launched?', '**Swachh Bharat Abhiyan (Clean India Mission)** was launched on **2 October 2014**, the birth anniversary of Mahatma Gandhi.

It aims to achieve **universal sanitation coverage** and eliminate open defecation, and is run jointly by the **Ministry of Jal Shakti** (rural) and the **Ministry of Housing and Urban Affairs** (urban).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00075', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 2, 'What is the objective of the Beti Bachao Beti Padhao scheme?', '**Beti Bachao Beti Padhao** was launched on **22 January 2015** at Panipat, Haryana, by the **Ministry of Women and Child Development**.

Its objective is to **address the declining child sex ratio** and promote the education and welfare of the girl child.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00076', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 3, 'What is the Pradhan Mantri Awas Yojana (PMAY)?', '**Pradhan Mantri Awas Yojana (PMAY)** was launched in **2015** by the **Ministry of Housing and Urban Affairs** with the goal of **"Housing for All."**

It has two components: **PMAY-Urban** for cities and **PMAY-Gramin** for rural areas, providing financial assistance for house construction.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00077', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 4, 'What is the "Make in India" initiative and which department runs it?', '**"Make in India"** was launched on **25 September 2014** to encourage companies to **manufacture their products in India**.

It is administered by the **Department for Promotion of Industry and Internal Trade (DPIIT)** under the Ministry of Commerce and Industry.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00078', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 5, 'What is the Digital India programme?', '**Digital India** was launched on **1 July 2015** by the **Ministry of Electronics and Information Technology (MeitY)**.

Its objective is to transform India into a **digitally empowered society and knowledge economy** through improved digital infrastructure and online service delivery.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00079', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 6, 'What is the goal of the Skill India Mission?', 'The **Skill India Mission** was launched in **2015** under the **Ministry of Skill Development and Entrepreneurship**.

Its goal is to **train and certify a large workforce** in industry-relevant skills to improve employability.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00080', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 7, 'What is the Startup India initiative and when was it launched?', '**Startup India** was launched on **16 January 2016** by the **DPIIT, Ministry of Commerce and Industry**.

It aims to build a **strong ecosystem for innovation and entrepreneurship**, offering startups tax benefits, easier compliance, and funding support.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00081', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 8, 'What is the Stand Up India scheme meant to achieve?', '**Stand Up India** was launched on **5 April 2016** by the **Ministry of Finance**.

It facilitates **bank loans between ₹10 lakh and ₹1 crore** to at least one Scheduled Caste/Scheduled Tribe borrower and one woman borrower per bank branch for setting up new enterprises.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00082', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 9, 'What is the Pradhan Mantri Ujjwala Yojana?', '**Pradhan Mantri Ujjwala Yojana (PMUY)** was launched on **1 May 2016** by the **Ministry of Petroleum and Natural Gas**.

Its objective is to provide **free LPG gas connections** to women from below-poverty-line (BPL) households, reducing reliance on unsafe cooking fuels.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00083', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 10, 'What is the Pradhan Mantri Fasal Bima Yojana (PMFBY)?', '**Pradhan Mantri Fasal Bima Yojana (PMFBY)** was launched in **2016** by the **Ministry of Agriculture and Farmers Welfare**.

It provides **crop insurance** to farmers against losses from natural calamities, pests, and diseases, at a low, uniform premium rate.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00084', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 11, 'What is the Pradhan Mantri Jeevan Jyoti Bima Yojana (PMJJBY)?', '**Pradhan Mantri Jeevan Jyoti Bima Yojana (PMJJBY)** was launched in **2015** by the **Ministry of Finance**.

It is a **one-year renewable life insurance scheme** offering a cover of **₹2 lakh** in case of death, available to individuals aged 18-50 with a bank account.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00085', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 12, 'What is the Pradhan Mantri Suraksha Bima Yojana (PMSBY)?', '**Pradhan Mantri Suraksha Bima Yojana (PMSBY)** was launched in **2015** by the **Ministry of Finance**.

It is an **accidental death and disability insurance scheme** offering a cover of **₹2 lakh**, originally priced at a very low annual premium.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00086', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 13, 'What is the Atal Pension Yojana (APY)?', '**Atal Pension Yojana (APY)** was launched in **2015**, administered by the **Pension Fund Regulatory and Development Authority (PFRDA)**.

It provides a **guaranteed minimum pension** to subscribers after the age of 60, targeted mainly at workers in the unorganised sector.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00087', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 14, 'What is MGNREGA and what does it guarantee?', 'The **Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA)** was enacted in **2005** under the **Ministry of Rural Development**.

It legally guarantees **100 days of wage employment per year** to every rural household whose adult members volunteer for unskilled manual work.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00088', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 15, 'What is Ayushman Bharat / PM-JAY and what does it provide?', '**Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana (PM-JAY)** was launched in **September 2018** by the **Ministry of Health and Family Welfare**.

It provides an annual **health cover of ₹5 lakh per family** for secondary and tertiary hospitalisation, making it one of the world''s largest government-funded health assurance schemes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00089', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 16, 'What is the Sukanya Samriddhi Yojana?', '**Sukanya Samriddhi Yojana** was launched in **2015** under the **"Beti Bachao Beti Padhao"** campaign, administered by the **Ministry of Finance**.

It is a **small savings scheme for the girl child**, allowing parents to open an account for a girl below the age of 10 to build funds for her education and marriage.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00090', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 17, 'What is the Pradhan Mantri Bhartiya Janaushadhi Pariyojana (PMBJP)?', 'The **Pradhan Mantri Bhartiya Janaushadhi Pariyojana**, run by the **Department of Pharmaceuticals**, promotes the sale of **quality generic medicines at affordable prices** through dedicated "Jan Aushadhi Kendras."

The scheme traces back to **2008** and was scaled up significantly from **2015** onward.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00091', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 18, 'What is the "One Nation One Ration Card" scheme?', '**"One Nation One Ration Card"** allows beneficiaries under the **National Food Security Act** to access their **entitled food grains from any Fair Price Shop across India**.

It uses **Aadhaar-linked biometric authentication** to ensure portability of ration benefits, particularly helping migrant workers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00092', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 19, 'When was the National Food Security Act enacted and what does it ensure?', 'The **National Food Security Act (NFSA)** was enacted in **2013**.

It legally entitles about **two-thirds of India''s population** to receive subsidised food grains under the **Public Distribution System (PDS)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00093', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 20, 'What is the Mid-Day Meal Scheme, and what is it now known as?', 'The **Mid-Day Meal Scheme**, launched in **1995**, provides **free cooked lunches to children in government schools** to improve nutrition and school attendance.

It was renamed the **"PM POSHAN" scheme in 2021**, administered by the Ministry of Education.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00094', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 21, 'What is the Integrated Child Development Services (ICDS) scheme?', 'The **Integrated Child Development Services (ICDS)** scheme was launched in **1975** by the **Ministry of Women and Child Development**.

It provides **nutrition, health, and pre-school education services** to children below six years of age, and to pregnant and lactating mothers, through "Anganwadi" centres.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00095', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 22, 'What was the Rashtriya Swasthya Bima Yojana (RSBY)?', '**Rashtriya Swasthya Bima Yojana (RSBY)** was launched in **2008** by the **Ministry of Labour and Employment**.

It provided **health insurance coverage to Below Poverty Line (BPL) families**, and is widely regarded as the predecessor to the later **Ayushman Bharat (PM-JAY)** scheme.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00096', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 23, 'What was the Sarva Shiksha Abhiyan?', '**Sarva Shiksha Abhiyan (SSA)** was launched in **2001** by the **Ministry of Education** to achieve **universal elementary education**.

It was later subsumed, along with other schemes, into the **integrated "Samagra Shiksha" scheme** launched in 2018.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00097', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 24, 'What does the Right to Education (RTE) Act, 2009 provide for?', 'The **Right of Children to Free and Compulsory Education (RTE) Act, 2009** came into force on **1 April 2010**.

It guarantees **free and compulsory education to all children aged 6 to 14 years** as a fundamental right under Article 21-A of the Constitution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00098', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 25, 'What is the Pradhan Mantri Gram Sadak Yojana (PMGSY)?', '**Pradhan Mantri Gram Sadak Yojana (PMGSY)** was launched in **2000** by the **Ministry of Rural Development**.

Its objective is to provide **all-weather road connectivity to unconnected rural habitations** across India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00099', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 26, 'What is the Pradhan Mantri Kaushal Vikas Yojana (PMKVY)?', '**Pradhan Mantri Kaushal Vikas Yojana (PMKVY)** was launched in **2015** under the **Ministry of Skill Development and Entrepreneurship**.

It offers **free short-duration skill training and certification** to youth, aligned with industry requirements, under the broader Skill India Mission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00100', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 27, 'What was the National Rural Health Mission (NRHM)?', 'The **National Rural Health Mission (NRHM)** was launched in **2005** by the **Ministry of Health and Family Welfare**.

It aimed to improve **healthcare delivery in rural areas**, and was later merged with the National Urban Health Mission to form the overarching **National Health Mission (NHM)** in 2013.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00101', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 28, 'What is the Smart Cities Mission?', 'The **Smart Cities Mission** was launched in **2015** by the **Ministry of Housing and Urban Affairs**.

It aims to develop selected cities with **sustainable and citizen-friendly infrastructure**, using technology-driven solutions for urban services.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00102', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 29, 'What is the AMRUT scheme?', '**AMRUT (Atal Mission for Rejuvenation and Urban Transformation)** was launched in **2015** by the **Ministry of Housing and Urban Affairs**.

It focuses on providing **basic urban infrastructure** such as water supply, sewerage, and green spaces in select towns and cities.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00103', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 30, 'What is the Namami Gange Programme?', 'The **Namami Gange Programme** was launched in **2014** under the **Ministry of Jal Shakti**.

It is an integrated conservation mission aimed at **cleaning and rejuvenating the River Ganga** and its tributaries.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00104', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 31, 'What is the Jawaharlal Nehru National Solar Mission?', 'The **Jawaharlal Nehru National Solar Mission** was launched in **2010** under the **National Action Plan on Climate Change**.

Its objective is to promote the development and deployment of **solar energy technology** in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00105', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 32, 'What is the UDAN scheme?', '**UDAN ("Ude Desh ka Aam Naagrik")** was launched in **2016** by the **Ministry of Civil Aviation**.

It is a **Regional Connectivity Scheme** designed to make air travel affordable and to connect underserved and unserved airports across India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00106', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 33, 'What is the Bharatmala Pariyojana?', '**Bharatmala Pariyojana** was launched in **2017** under the **Ministry of Road Transport and Highways**.

It is an umbrella programme for developing **national highways and expressway corridors** to improve freight and passenger movement efficiency.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00107', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 34, 'What is the Sagarmala Project?', 'The **Sagarmala Project** was launched in **2015** by the **Ministry of Ports, Shipping and Waterways**.

It focuses on **port-led development**, aiming to modernise ports and improve coastal and inland waterway connectivity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00108', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 35, 'What is the PM Gati Shakti National Master Plan?', '**PM Gati Shakti** was launched in **October 2021**.

It is a **digital platform for integrated infrastructure planning**, bringing together various ministries to coordinate multi-modal connectivity projects.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00109', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 36, 'What is the PM SVANidhi scheme?', '**PM SVANidhi (PM Street Vendor''s AtmaNirbhar Nidhi)** was launched in **2020** by the **Ministry of Housing and Urban Affairs**.

It provides **collateral-free working capital loans** to street vendors to help them resume their livelihoods.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00110', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 37, 'What is the Atmanirbhar Bharat Abhiyan?', '**Atmanirbhar Bharat Abhiyan ("Self-Reliant India Mission")** was announced in **May 2020**.

It is a broad economic strategy aimed at making India **self-reliant across sectors** such as manufacturing, agriculture, and defence, while still engaging with the global economy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00111', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 38, 'What is the Production Linked Incentive (PLI) scheme?', 'The **Production Linked Incentive (PLI) scheme** was introduced in **2020** by the **Ministry of Commerce and Industry**.

It offers **financial incentives to manufacturers** based on incremental sales of goods produced in India, across sectors such as electronics, pharmaceuticals, and textiles.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00112', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 39, 'What is the National Pension System (NPS)?', 'The **National Pension System (NPS)** was introduced in **2004** for new government employees, and was **opened to all citizens in 2009**.

It is a **voluntary, defined-contribution pension scheme** regulated by the **Pension Fund Regulatory and Development Authority (PFRDA)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00113', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 40, 'What is the Employees'' Provident Fund (EPF) and which body administers it?', 'The **Employees'' Provident Fund (EPF)** was established under the **Employees'' Provident Funds Act, 1952**.

It is administered by the **Employees'' Provident Fund Organisation (EPFO)** and provides retirement savings benefits to salaried employees.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00114', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 41, 'What is the Antyodaya Anna Yojana?', '**Antyodaya Anna Yojana (AAY)** was launched in **2000** by the **Ministry of Consumer Affairs, Food and Public Distribution**.

It provides **highly subsidised food grains** to the poorest of poor families identified under the Public Distribution System.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00115', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 42, 'What is the Deendayal Antyodaya Yojana - National Rural Livelihood Mission (DAY-NRLM)?', 'The **National Rural Livelihood Mission** was launched in **2011** and renamed **Deendayal Antyodaya Yojana-NRLM** in 2015, under the **Ministry of Rural Development**.

Its objective is to **reduce rural poverty** by organising women into self-help groups and promoting sustainable livelihoods.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00116', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 43, 'What is the Pradhan Mantri Mudra Yojana (PMMY)?', '**Pradhan Mantri Mudra Yojana (PMMY)** was launched in **2015** by the **Ministry of Finance**.

It provides **collateral-free loans up to ₹10 lakh** to micro and small enterprises, categorised under three tiers: **Shishu, Kishor, and Tarun**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00117', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 44, 'What is the Pradhan Mantri Vaya Vandana Yojana (PMVVY)?', '**Pradhan Mantri Vaya Vandana Yojana (PMVVY)** was launched in **2017**, implemented through the **Life Insurance Corporation of India (LIC)**.

It is a **pension scheme for senior citizens** aged 60 and above, offering a guaranteed return over a fixed policy term.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00118', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 45, 'What is the Pradhan Mantri Matru Vandana Yojana (PMMVY)?', '**Pradhan Mantri Matru Vandana Yojana (PMMVY)** was launched in **2017** by the **Ministry of Women and Child Development**.

It provides a **cash incentive to pregnant and lactating mothers** for their first living child, to support nutrition and partially compensate for wage loss.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00119', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 46, 'What is the POSHAN Abhiyaan?', '**POSHAN Abhiyaan (National Nutrition Mission)** was launched in **2018** by the **Ministry of Women and Child Development**.

It aims to improve **nutritional outcomes for children, adolescent girls, pregnant women, and lactating mothers** across India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00120', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 47, 'What is the National Health Mission (NHM)?', 'The **National Health Mission (NHM)** was formed in **2013** by merging the **National Rural Health Mission** and the **National Urban Health Mission**.

It functions under the **Ministry of Health and Family Welfare** to strengthen healthcare systems across both rural and urban India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00121', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 48, 'What is the e-Shram portal?', 'The **e-Shram portal** was launched in **2021** by the **Ministry of Labour and Employment**.

It creates a **national database of unorganised sector workers**, issuing each worker a unique **e-Shram card** to facilitate access to social security benefits.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00122', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 49, 'What does the Right to Information (RTI) Act, 2005 provide for?', 'The **Right to Information (RTI) Act** was enacted in **2005**.

It empowers citizens to **request information from public authorities**, promoting transparency and accountability in government functioning.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00123', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 50, 'When was the Goods and Services Tax (GST) implemented in India?', '**Goods and Services Tax (GST)** was implemented across India from **1 July 2017**.

It replaced multiple indirect taxes levied by the Centre and states with a **single unified tax system**, under the principle of "One Nation, One Tax."', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00124', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 51, 'What is Direct Benefit Transfer (DBT) and what does the "JAM Trinity" refer to?', '**Direct Benefit Transfer (DBT)** was launched in **2013** to transfer government subsidies and benefits **directly into beneficiaries'' bank accounts**.

The **"JAM Trinity"** refers to the combination of **Jan Dhan accounts, Aadhaar, and Mobile numbers** that underpins this system.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00125', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 52, 'What is Aadhaar and which body issues it?', '**Aadhaar** is a **12-digit unique identification number** issued by the **Unique Identification Authority of India (UIDAI)**, established in **2009**.

It is based on an individual''s **demographic and biometric data** and serves as a proof of identity across India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00126', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 53, 'What was the Indira Awaas Yojana?', '**Indira Awaas Yojana (IAY)** was launched in **1985** by the **Ministry of Rural Development**.

It provided **financial assistance for house construction to rural poor families**, and was restructured and renamed **"Pradhan Mantri Awas Yojana - Gramin"** in 2016.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00127', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 54, 'What is the PM-Kisan Samman Nidhi scheme?', '**PM-Kisan Samman Nidhi** was launched in **2019** by the **Ministry of Agriculture and Farmers Welfare**.

It provides eligible farmer families with an income support of **₹6,000 per year**, paid in three equal instalments directly into their bank accounts.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00128', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 55, 'What is the Kisan Credit Card (KCC) scheme?', 'The **Kisan Credit Card (KCC) scheme** was introduced in **1998**.

It provides farmers with **timely and affordable credit** for their agricultural and allied needs through a simplified credit delivery mechanism.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00129', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 56, 'What is the Soil Health Card Scheme?', 'The **Soil Health Card Scheme** was launched in **2015** by the **Ministry of Agriculture and Farmers Welfare**.

It provides farmers with information on the **nutrient status of their soil**, along with recommendations on appropriate fertiliser dosages to improve productivity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00130', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 57, 'What is the Pradhan Mantri Krishi Sinchayee Yojana (PMKSY)?', '**Pradhan Mantri Krishi Sinchayee Yojana (PMKSY)** was launched in **2015** under the slogan **"Har Khet Ko Pani"** ("water to every field").

It aims to expand **irrigation coverage** and improve water-use efficiency in Indian agriculture.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00131', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 58, 'What is e-NAM (National Agriculture Market)?', '**e-NAM (National Agriculture Market)** was launched in **2016** by the **Ministry of Agriculture and Farmers Welfare**.

It is a **pan-India electronic trading platform** that networks existing agricultural markets (mandis) to create a unified national market for farm produce.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00132', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 59, 'What is the Van Dhan Yojana?', 'The **Van Dhan Yojana** was launched in **2018** under the **Ministry of Tribal Affairs**.

It aims to improve the **livelihoods of tribal communities** by promoting value addition to minor forest produce through cluster-based enterprises.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00133', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 60, 'What are Eklavya Model Residential Schools (EMRS)?', '**Eklavya Model Residential Schools (EMRS)** are residential schools established under the **Ministry of Tribal Affairs**, with the scheme dating to **1997-98** and significantly expanded from 2018 onward.

They provide **quality education to tribal (Scheduled Tribe) students** in remote areas, modelled on the lines of Navodaya Vidyalayas.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00134', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 61, 'What is the National Livestock Mission?', 'The **National Livestock Mission** was launched in **2014-15** by the **Ministry of Fisheries, Animal Husbandry and Dairying**.

It aims to promote **sustainable development of the livestock sector**, including improved breeding, feed, and fodder availability.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00135', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 62, 'What is Operation Greens, launched by the government?', '**Operation Greens** was launched in **2018** by the **Ministry of Food Processing Industries**.

It initially focused on stabilising the supply of **Tomato, Onion, and Potato (the "TOP" crops)** and was later expanded to cover other perishables.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00136', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 63, 'What is the One District One Product (ODOP) initiative?', 'The **One District One Product (ODOP)** initiative aims to identify, promote, and brand **one unique product from each district** of India.

It supports local industries, artisans, and exporters, and is linked with schemes like the **PM Formalisation of Micro Food Processing Enterprises (PM-FME)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00137', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 64, 'What is the objective of the National Rural Drinking Water Programme / Jal Jeevan Mission?', 'The **Jal Jeevan Mission** was launched in **2019** by the **Ministry of Jal Shakti**.

Its objective is to provide **functional household tap connections ("Har Ghar Jal")** to every rural household in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00138', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 65, 'What is the Jawaharlal Nehru National Urban Renewal Mission (JNNURM)?', 'The **Jawaharlal Nehru National Urban Renewal Mission (JNNURM)** was launched in **2005**.

It aimed at **planned urban infrastructure development and governance reform** in Indian cities, and is considered a precursor to later missions like AMRUT and the Smart Cities Mission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00139', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 66, 'What is the National Apprenticeship Promotion Scheme (NAPS)?', 'The **National Apprenticeship Promotion Scheme (NAPS)** was launched in **2016** by the **Ministry of Skill Development and Entrepreneurship**.

It promotes apprenticeship training by sharing **part of the stipend cost** with employers who engage apprentices.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00140', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 67, 'What is the Pradhan Mantri Garib Kalyan Yojana?', 'The **Pradhan Mantri Garib Kalyan Yojana (PMGKY)** was announced in **March 2020** in response to the COVID-19 pandemic.

It provided **free food grains and direct cash transfers** to vulnerable sections of the population during the crisis.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00141', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 68, 'What is the Deen Dayal Upadhyaya Gram Jyoti Yojana (DDUGJY)?', '**Deen Dayal Upadhyaya Gram Jyoti Yojana (DDUGJY)** was launched in **2015** by the **Ministry of Power**.

It focuses on **rural electrification** and strengthening sub-transmission and distribution infrastructure in villages.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00142', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 69, 'What is the Mission Indradhanush programme?', '**Mission Indradhanush** was launched in **2014** by the **Ministry of Health and Family Welfare**.

It aims to achieve **full immunisation coverage** for children and pregnant women against vaccine-preventable diseases.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00143', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 70, 'What is the National Digital Health Mission (Ayushman Bharat Digital Mission)?', 'The **Ayushman Bharat Digital Mission (ABDM)** was launched nationwide in **September 2021**.

It aims to create a **digital health ecosystem**, including a unique health ID for citizens, to enable seamless access to health records across providers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00144', 'current-affairs-gk-bank', 'Government Schemes & Policies', 1, 71, 'What is the Pradhan Mantri Shram Yogi Maan-dhan (PM-SYM) scheme?', '**Pradhan Mantri Shram Yogi Maan-dhan (PM-SYM)** was launched in **2019** by the **Ministry of Labour and Employment**.

It is a **voluntary pension scheme for unorganised sector workers**, guaranteeing a minimum monthly pension of ₹3,000 after the age of 60.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00145', 'current-affairs-gk-bank', 'Sports', 2, 0, 'The Ranji Trophy is associated with which sport, and after whom is it named?', 'The **Ranji Trophy** is India''s premier **domestic first-class cricket championship**.

It is named after **Ranjitsinhji**, a legendary Indian cricketer who also played Test cricket for England, and the tournament began in the **1934-35 season**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00146', 'current-affairs-gk-bank', 'Sports', 2, 1, 'What is the Davis Cup and which sport does it belong to?', 'The **Davis Cup** is the premier **men''s international team tennis** competition.

It was first contested in **1900** between the United States and Great Britain, and is organised by the **International Tennis Federation (ITF)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00147', 'current-affairs-gk-bank', 'Sports', 2, 2, 'Which is considered the oldest tennis tournament in the world?', '**Wimbledon** is considered the **oldest tennis tournament** in the world, first held in **1877** in London.

It is the only Grand Slam event still played on **grass courts**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00148', 'current-affairs-gk-bank', 'Sports', 2, 3, 'What were India''s hockey achievements during their "golden era" at the Olympics?', 'India experienced a **golden era in Olympic hockey**, winning **gold medals in six consecutive Olympics from 1928 to 1956**.

Overall, India has won a total of **eight Olympic gold medals in hockey**, the most recent being in **1980 at Moscow**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00149', 'current-affairs-gk-bank', 'Sports', 2, 4, 'Who is known as the "Wizard of Hockey" in Indian sport?', '**Major Dhyan Chand** is known as the **"Wizard of Hockey"** (or "Hockey ka Jadugar").

He played a central role in India''s hockey gold medals at the **1928, 1932, and 1936 Olympics**, and India''s National Sports Day is observed on his birthday, **29 August**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00150', 'current-affairs-gk-bank', 'Sports', 2, 5, 'What is the Durand Cup and what is its significance?', 'The **Durand Cup** is a football tournament founded in **1888** by Sir Mortimer Durand.

It is recognised as the **oldest football tournament in Asia** and the third-oldest in the world still being played.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00151', 'current-affairs-gk-bank', 'Sports', 2, 6, 'What is the Santosh Trophy?', 'The **Santosh Trophy** is the **national football championship of India**, contested between teams representing different states and units.

It was first held in **1941** and is named after Maharaja Sir Manmatha Nath Roy Chowdhury of Santosh.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00152', 'current-affairs-gk-bank', 'Sports', 2, 7, 'What is the Sultan Azlan Shah Cup, and which sport is it associated with?', 'The **Sultan Azlan Shah Cup** is an **international field hockey tournament** held in Malaysia.

It was first organised in **1983** and is named after the former King of Malaysia, Sultan Azlan Shah, who was also a former president of the Malaysian Hockey Federation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00153', 'current-affairs-gk-bank', 'Sports', 2, 8, 'When and where was the first FIFA World Cup held?', 'The **first FIFA World Cup** was held in **1930** in **Uruguay**.

The host nation, **Uruguay**, also won the inaugural tournament, defeating Argentina in the final.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00154', 'current-affairs-gk-bank', 'Sports', 2, 9, 'Who is credited with founding the modern Olympic Games, and when were they first held?', 'The modern Olympic Games were founded by **Baron Pierre de Coubertin**, who also established the **International Olympic Committee (IOC) in 1894**.

The first modern Olympics were held in **1896 in Athens, Greece**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00155', 'current-affairs-gk-bank', 'Sports', 2, 10, 'What do the five rings of the Olympic symbol represent?', 'The **five interlocking rings** of the Olympic symbol represent the **five inhabited continents** — Africa, the Americas, Asia, Europe, and Oceania.

The rings, in blue, yellow, black, green, and red, were designed by Pierre de Coubertin and introduced in **1913**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00156', 'current-affairs-gk-bank', 'Sports', 2, 11, 'What is the official motto of the Olympic Games?', 'The official Olympic motto is **"Citius, Altius, Fortius"**, a Latin phrase meaning **"Faster, Higher, Stronger."**

In 2021, the IOC added the word **"Communiter"** ("Together") to the motto.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00157', 'current-affairs-gk-bank', 'Sports', 2, 12, 'When and where was the first Asian Games held?', 'The **first Asian Games** were held in **New Delhi, India, in 1951**.

They are organised by the **Olympic Council of Asia (OCA)** and held once every four years.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00158', 'current-affairs-gk-bank', 'Sports', 2, 13, 'What were the Commonwealth Games originally known as?', 'The **Commonwealth Games** were originally known as the **British Empire Games**, first held in **1930** in Hamilton, Canada.

They are held every four years among nations of the **Commonwealth of Nations**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00159', 'current-affairs-gk-bank', 'Sports', 2, 14, 'When and where was the first Cricket World Cup held, and who won it?', 'The **first Cricket World Cup** was held in **1975 in England**.

The tournament, played in the **One Day International (ODI)** format, was won by the **West Indies**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00160', 'current-affairs-gk-bank', 'Sports', 2, 15, 'When did India first win the Cricket World Cup, and who was the captain?', 'India won its **first Cricket World Cup in 1983**, defeating the West Indies in the final at **Lord''s**.

The team was captained by **Kapil Dev**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00161', 'current-affairs-gk-bank', 'Sports', 2, 16, 'When was the first ICC T20 World Cup held, and which team won it?', 'The **first ICC T20 World Cup** was held in **2007 in South Africa**.

**India** won the inaugural tournament, defeating Pakistan in the final, under the captaincy of **M. S. Dhoni**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00162', 'current-affairs-gk-bank', 'Sports', 2, 17, 'In which sport is the term "love" used to denote a zero score?', 'The term **"love"**, meaning a score of zero, is used in **tennis** (and also in badminton and squash).

It is believed to derive from the French word *"l''oeuf"* (egg), referencing the shape of a zero.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00163', 'current-affairs-gk-bank', 'Sports', 2, 18, 'In which sport is the term "googly" used, and what does it mean?', 'The term **"googly"** is used in **cricket**.

It refers to a type of **deceptive delivery bowled by a leg-spin bowler** that turns in the opposite direction to what the batsman expects.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00164', 'current-affairs-gk-bank', 'Sports', 2, 19, 'What are the Thomas Cup and Uber Cup?', 'The **Thomas Cup** and **Uber Cup** are the premier **international team badminton championships** for men''s and women''s teams respectively.

The Thomas Cup was first held in **1948-49**, and the Uber Cup followed in **1956-57**; both are organised by the **Badminton World Federation (BWF)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00165', 'current-affairs-gk-bank', 'Sports', 2, 20, 'Who was the first Indian to become a Chess Grandmaster?', '**Viswanathan Anand** became **India''s first Chess Grandmaster** in **1988**.

He went on to become a **five-time World Chess Champion**, one of the most successful chess players in history.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00166', 'current-affairs-gk-bank', 'Sports', 2, 21, 'Chess is believed to have originated in India under what ancient name?', 'Chess is believed to have originated in India as a game called **"Chaturanga"** around the **6th century CE**.

The game later spread to Persia and the Arab world before evolving into the modern form of chess played today.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00167', 'current-affairs-gk-bank', 'Sports', 2, 22, 'When was the Pro Kabaddi League founded in India?', 'The **Pro Kabaddi League (PKL)** was founded in **2014**, modelled on the format of the Indian Premier League (IPL).

It significantly boosted the **popularity and professionalisation of kabaddi**, a traditional Indian contact sport, within the country.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00168', 'current-affairs-gk-bank', 'Sports', 2, 23, 'What does the cricketing term "hat-trick" refer to, and what is its origin?', 'A **"hat-trick"** in cricket refers to a bowler taking **three wickets with three consecutive deliveries**.

The term is believed to have originated in 19th-century English cricket, where a bowler achieving this feat was sometimes presented with a **hat** as a reward.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00169', 'current-affairs-gk-bank', 'Sports', 2, 24, 'Where is FIFA headquartered, and when was it founded?', '**FIFA (Fédération Internationale de Football Association)** is headquartered in **Zurich, Switzerland**.

It was founded in **1904** and serves as the **international governing body of football**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00170', 'current-affairs-gk-bank', 'Sports', 2, 25, 'Where is the International Olympic Committee (IOC) headquartered?', 'The **International Olympic Committee (IOC)** is headquartered in **Lausanne, Switzerland**.

It was founded in **1894** by Baron Pierre de Coubertin and is responsible for organising the Olympic Games.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00171', 'current-affairs-gk-bank', 'Sports', 2, 26, 'When was the Board of Control for Cricket in India (BCCI) founded, and where is it headquartered?', 'The **Board of Control for Cricket in India (BCCI)** was founded in **1928**.

It is headquartered in **Mumbai** and is the national governing body for cricket in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00172', 'current-affairs-gk-bank', 'Sports', 2, 27, 'When was the International Cricket Council (ICC) founded, and where is it headquartered?', 'The governing body of international cricket was founded in **1909** as the **"Imperial Cricket Conference,"** and was renamed the **International Cricket Council (ICC)** in **1989**.

Its headquarters has been located in **Dubai, UAE**, since 2005.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00173', 'current-affairs-gk-bank', 'Sports', 2, 28, 'What is the All England Open Badminton Championships?', 'The **All England Open Badminton Championships** is considered the **oldest and most prestigious badminton tournament** in the world.

It was first held in **1899**, in Guildford, England.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00174', 'current-affairs-gk-bank', 'Sports', 2, 29, 'What are the four Grand Slam tournaments in tennis?', 'The four **Grand Slam tournaments** in tennis are the **Australian Open, the French Open (Roland Garros), Wimbledon, and the US Open**.

Winning all four Grand Slam titles in the same calendar year is referred to as a **"Calendar Grand Slam."**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00175', 'current-affairs-gk-bank', 'Sports', 2, 30, 'Where does the Olympic flame tradition originate from?', 'The **Olympic flame** is traditionally lit at **Olympia, Greece**, the site of the ancient Olympic Games, using the rays of the sun and a parabolic mirror.

It is then carried via a relay — the **Olympic torch relay** — to the host city of the Games.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00176', 'current-affairs-gk-bank', 'Sports', 2, 31, 'Who was the first Indian to win an individual Olympic gold medal?', '**Abhinav Bindra** became the **first Indian to win an individual Olympic gold medal**, in **shooting (10m air rifle)** at the **2008 Beijing Olympics**.

This remains India''s only individual Olympic gold medal in an event other than hockey (a team sport).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00177', 'current-affairs-gk-bank', 'Sports', 2, 32, 'Who was the first Indian woman to win an Olympic medal?', '**Karnam Malleswari** became the **first Indian woman to win an Olympic medal**, winning a **bronze medal in weightlifting** at the **2000 Sydney Olympics**.

She competed in the **69 kg category**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00178', 'current-affairs-gk-bank', 'Sports', 2, 33, 'In cricket, what is a "duck"?', 'A **"duck"** in cricket refers to a batsman being **dismissed without scoring any runs**.

A **"golden duck"** specifically refers to being dismissed off the very first ball faced.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00179', 'current-affairs-gk-bank', 'Sports', 2, 34, 'What is the standard length of a cricket pitch?', 'A standard **cricket pitch** measures **22 yards (20.12 metres)** in length, between the two sets of stumps.

This measurement is also historically equal to **one chain**, a traditional unit of length.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00180', 'current-affairs-gk-bank', 'Sports', 2, 35, 'How many players from each team are on the field in a standard football match?', 'In a standard football (soccer) match, each team fields **11 players**, including one goalkeeper.

A match is typically played over **two halves of 45 minutes each**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00181', 'current-affairs-gk-bank', 'Sports', 2, 36, 'How many players from each team are on the field in kabaddi?', 'In **kabaddi**, each team fields **7 players** on the court at a time.

The game is played between two teams in a divided court, with raiders attempting to tag defenders and return to their own half in a single breath.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00182', 'current-affairs-gk-bank', 'Sports', 2, 37, 'How many players from each side are on the field in field hockey?', 'In **field hockey**, each team fields **11 players**, including a goalkeeper.

A standard match is played over **four quarters**, under rules set by the **International Hockey Federation (FIH)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00183', 'current-affairs-gk-bank', 'Sports', 2, 38, 'How many players from each team are on the court in volleyball?', 'In **volleyball**, each team has **6 players** on the court at any given time.

Matches are typically played in a **best-of-five sets** format.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00184', 'current-affairs-gk-bank', 'Sports', 2, 39, 'How many players from each team are on the court in basketball?', 'In **basketball**, each team fields **5 players** on the court at a time.

The game is played over **four quarters**, and is governed internationally by **FIBA**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00185', 'current-affairs-gk-bank', 'Sports', 2, 40, 'In tennis and badminton, what does the term "deuce" mean?', '**"Deuce"** refers to a **tied score** late in a game (typically 40-40 in tennis, or 20-20 in badminton), after which a player must win by a margin of **two clear points**.

The term is used to determine the winner of a close game.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00186', 'current-affairs-gk-bank', 'Sports', 2, 41, 'What is FIDE, and when was it founded?', '**FIDE (Fédération Internationale des Échecs)**, the **International Chess Federation**, was founded in **1924 in Paris**.

It governs international chess competition, including the **World Chess Championship** and official chess ratings.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00187', 'current-affairs-gk-bank', 'Sports', 2, 42, 'What is the origin of the chess term "checkmate"?', 'The term **"checkmate"** is derived from the Persian phrase **"Shah Mat,"** meaning **"the king is helpless/defeated."**

It signifies the end of a chess game, where the king is in check and cannot escape capture.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00188', 'current-affairs-gk-bank', 'Sports', 2, 43, 'Which Indian sprinter is known as the "Flying Sikh"?', '**Milkha Singh** is famously known as the **"Flying Sikh"**.

He was a celebrated Indian track and field athlete, renowned for his performances in the **400m event** during the 1950s and 1960s.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00189', 'current-affairs-gk-bank', 'Sports', 2, 44, 'Which Indian cricketer is known as the "Haryana Hurricane"?', '**Kapil Dev** is known as the **"Haryana Hurricane"**.

He was an all-rounder who captained India to its **first Cricket World Cup win in 1983**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00190', 'current-affairs-gk-bank', 'Sports', 2, 45, 'Which Indian cricketer is popularly known as the "Little Master"?', '**Sunil Gavaskar** is popularly known as the **"Little Master"**, a nickname later also associated with **Sachin Tendulkar** in some contexts.

Gavaskar was the **first batsman in Test cricket history to score 10,000 runs**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00191', 'current-affairs-gk-bank', 'Sports', 2, 46, 'Which Indian cricketer is popularly known as the "Master Blaster"?', '**Sachin Tendulkar** is popularly known as the **"Master Blaster."**

He holds numerous batting records, including being the **first player to score 100 international centuries** across Test and ODI cricket.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00192', 'current-affairs-gk-bank', 'Sports', 2, 47, 'When and where was the first-ever Test cricket match played?', 'The **first-ever Test cricket match** was played in **March 1877** between **Australia and England** at the **Melbourne Cricket Ground**.

Test cricket is the longest format of the sport, traditionally played over up to five days.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00193', 'current-affairs-gk-bank', 'Sports', 2, 48, 'When and where did India play its first Test match?', 'India played its **first Test match in 1932**, against **England at Lord''s, London**.

The team was captained by the **Maharaja of Porbandar**, though **C. K. Nayudu** led the side on the field as vice-captain.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00194', 'current-affairs-gk-bank', 'Sports', 2, 49, 'Who captained the Indian cricket team in its first-ever Test match at Lord''s in 1932?', '**C. K. Nayudu** effectively led the Indian team on the field in its **first Test match in 1932**, and is widely regarded as **India''s first great cricket captain**.

He later became the first Indian cricketer to be honoured with the **Wisden Cricketer of the Year** award, in 1933.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00195', 'current-affairs-gk-bank', 'Sports', 2, 50, 'In cricket, what is a "maiden over"?', 'A **"maiden over"** in cricket is an over in which **no runs are scored off the bat** by the batsman.

It reflects tight, economical bowling and is an important statistic for judging a bowler''s control.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00196', 'current-affairs-gk-bank', 'Sports', 2, 51, 'When and where were the first Winter Olympic Games held?', 'The **first Winter Olympic Games** were held in **1924** in **Chamonix, France**.

They are held separately from the Summer Olympics, traditionally in the same calendar-cycle years before changing to an alternating schedule from 1994.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00197', 'current-affairs-gk-bank', 'Sports', 2, 52, 'In tennis, what is an "ace"?', 'An **"ace"** in tennis is a **legal serve that is not touched by the receiver**, winning the point outright.

It is one of the key offensive weapons for players with powerful serves.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00198', 'current-affairs-gk-bank', 'Sports', 2, 53, 'What material is traditionally used to make a shuttlecock in badminton?', 'A traditional **shuttlecock** is made using **16 overlapping feathers**, typically from a goose or duck, fixed into a rounded cork base.

Synthetic shuttlecocks made of nylon are also widely used as a more durable, cheaper alternative.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00199', 'current-affairs-gk-bank', 'Sports', 2, 54, 'How many squares does a chessboard have?', 'A standard **chessboard** has **64 squares**, arranged in an **8x8 grid** of alternating light and dark colours.

Each player begins with **16 pieces**: one king, one queen, two rooks, two bishops, two knights, and eight pawns.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00200', 'current-affairs-gk-bank', 'Sports', 2, 55, 'Who was the first undisputed World Chess Champion?', '**Wilhelm Steinitz** became the **first undisputed World Chess Champion** in **1886**, after defeating Johannes Zukertort in a championship match.

He held the title until 1894, when he lost to Emanuel Lasker.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00201', 'current-affairs-gk-bank', 'Sports', 2, 56, 'In boxing, what does the abbreviation "TKO" stand for?', '**"TKO"** stands for **"Technical Knockout."**

It occurs when a **referee, doctor, or a boxer''s own corner stops the fight**, judging that the boxer cannot continue safely, even though no formal knockout count has been completed.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00202', 'current-affairs-gk-bank', 'Sports', 2, 57, 'Which sport uses a "puck" instead of a ball?', '**Ice hockey** uses a **puck**, a hard rubber disc, instead of a ball.

The game is played on an ice rink between two teams, each typically fielding **six players**, including a goaltender.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00203', 'current-affairs-gk-bank', 'Sports', 2, 58, 'What is the Major Dhyan Chand National Stadium, and where is it located?', 'The **Major Dhyan Chand National Stadium** is located in **New Delhi** and is India''s principal venue historically associated with **field hockey**.

It was renamed in honour of hockey legend **Major Dhyan Chand** in 2002.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00204', 'current-affairs-gk-bank', 'Sports', 2, 59, 'In cricket, what does "LBW" stand for?', '**"LBW"** stands for **"Leg Before Wicket."**

It is a method of dismissal in which the ball strikes the batsman''s leg (or body) in line with the stumps, in a manner that would have otherwise hit the wicket.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00205', 'current-affairs-gk-bank', 'Sports', 2, 60, 'In which year did India win its first Olympic gold medal in hockey?', 'India won its **first Olympic gold medal in hockey in 1928**, at the **Amsterdam Olympics**.

This victory marked the beginning of India''s dominant run in Olympic hockey through the subsequent decades.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00206', 'current-affairs-gk-bank', 'Sports', 2, 61, 'In football, what is a "free kick"?', 'A **"free kick"** in football is awarded to a team following a **foul committed by the opposing team**.

It can be either a **"direct free kick,"** from which a goal can be scored directly, or an **"indirect free kick,"** which must first touch another player.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00207', 'current-affairs-gk-bank', 'Sports', 2, 62, 'In wrestling, what does it mean to "pin" an opponent?', 'A **"pin"** (or "fall") in wrestling occurs when a wrestler holds both of the opponent''s shoulders against the mat for a required period.

This immediately ends the bout in favour of the wrestler who achieved the pin.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00208', 'current-affairs-gk-bank', 'Sports', 2, 63, 'What does the term "love-all" signify at the start of a tennis or badminton match?', '**"Love-all"** is the term used by the umpire to indicate that the **score is 0-0** at the beginning of a game.

It reflects the use of **"love"** as the term for a zero score in these sports.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00209', 'current-affairs-gk-bank', 'Sports', 2, 64, 'What is the significance of the Jules Rimet Trophy in football history?', 'The **Jules Rimet Trophy** was the original trophy awarded to **FIFA World Cup** winners, named after the FIFA president who initiated the tournament.

**Brazil** was permitted to keep the trophy permanently in **1970** after winning the World Cup for the third time; it was later stolen and never recovered.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00210', 'current-affairs-gk-bank', 'Sports', 2, 65, 'What is the standard distance of a marathon race?', 'The standard distance of a **marathon** is **42.195 kilometres (26.2 miles)**.

This distance was standardised for the **1908 London Olympics** and has remained the official marathon distance ever since.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00211', 'current-affairs-gk-bank', 'Sports', 2, 66, 'In archery, what is the term for the central circle of the target called?', 'The central circle of an archery target is called the **"bullseye."**

Hitting the bullseye earns the **highest possible score** for that shot, typically **10 points** in standard target archery.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00212', 'current-affairs-gk-bank', 'Sports', 2, 67, 'What is the significance of the term "silly point" in cricket?', '**"Silly point"** is a **close-in fielding position** on the off side, near the batsman, used mainly against slow bowling.

The term "silly" reflects the **risk involved** in fielding so close to the bat.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00213', 'current-affairs-gk-bank', 'Sports', 2, 68, 'Which sport is governed internationally by World Athletics (formerly the IAAF)?', '**World Athletics**, formerly known as the **International Association of Athletics Federations (IAAF)**, is the global governing body for **track and field athletics**.

It was founded in **1912** and is headquartered in **Monaco**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00214', 'current-affairs-gk-bank', 'Sports', 2, 69, 'What is the National Sports Day of India, and why is that date chosen?', '**National Sports Day** in India is observed on **29 August** every year.

The date marks the **birth anniversary of hockey legend Major Dhyan Chand**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00215', 'current-affairs-gk-bank', 'Sports', 2, 70, 'What does the term "bye" mean in cricket scoring?', 'A **"bye"** in cricket is a run scored when the ball passes the batsman **without being touched by the bat or body**, and the batsmen choose to run.

It is recorded separately as **extras** rather than credited to any batsman.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00216', 'current-affairs-gk-bank', 'Sports', 2, 71, 'What is the origin and meaning of the term "pole position" in motorsport?', '**"Pole position"** refers to the **first starting position on the grid** in a motor race, awarded to the driver with the fastest qualifying time.

The term originates from **horse racing**, where the inside position near a "pole" marker was considered advantageous.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00217', 'current-affairs-gk-bank', 'Awards & Honours', 3, 0, 'What is the Bharat Ratna, and when was it instituted?', 'The **Bharat Ratna** is India''s **highest civilian award**, instituted in **1954**.

It is conferred for **exceptional service towards the advancement of art, literature, science, and public service** of the highest order.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00218', 'current-affairs-gk-bank', 'Awards & Honours', 3, 1, 'Who were the first recipients of the Bharat Ratna?', 'The **Bharat Ratna** was first conferred in **1954** on three recipients: **C. Rajagopalachari, Dr. Sarvepalli Radhakrishnan, and Dr. C. V. Raman**.

All three were honoured for their distinguished contributions in public affairs, philosophy, and science respectively.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00219', 'current-affairs-gk-bank', 'Awards & Honours', 3, 2, 'Who recommends the Bharat Ratna award, and who formally confers it?', 'The **Bharat Ratna** is conferred by the **President of India**, based on recommendations made by the **Prime Minister**.

Notably, there is **no formal statute** restricting the award to a fixed number of recipients each year.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00220', 'current-affairs-gk-bank', 'Awards & Honours', 3, 3, 'What shape is the Bharat Ratna medal, and what is inscribed on it?', 'The **Bharat Ratna medal** is shaped like a **peepal leaf**, with a **sun motif** and the words **"Bharat Ratna"** inscribed in Devanagari script.

Unlike most other awards, it carries **no cash grant or privileges**, besides the formal recognition and precedence it confers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00221', 'current-affairs-gk-bank', 'Awards & Honours', 3, 4, 'What are the Padma Awards, and what are their three categories?', 'The **Padma Awards**, instituted in **1954**, are India''s major civilian honours after the Bharat Ratna.

They comprise three categories in descending order of distinction: **Padma Vibhushan, Padma Bhushan, and Padma Shri**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00222', 'current-affairs-gk-bank', 'Awards & Honours', 3, 5, 'On which day are the Padma Awards traditionally announced each year?', 'The **Padma Awards** are traditionally announced on the eve of **Republic Day (26 January)** each year.

The formal investiture ceremonies are held later at the **Rashtrapati Bhavan**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00223', 'current-affairs-gk-bank', 'Awards & Honours', 3, 6, 'What is the Param Vir Chakra, and when was it instituted?', 'The **Param Vir Chakra (PVC)** is India''s **highest military decoration**, awarded for the **highest degree of valour** displayed in the presence of the enemy.

It was instituted in **1950**, and its first recipient was **Major Somnath Sharma**, honoured posthumously for his actions in the **1947-48 Indo-Pakistani War**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00224', 'current-affairs-gk-bank', 'Awards & Honours', 3, 7, 'What is the Ashoka Chakra, and when is it awarded?', 'The **Ashoka Chakra** is India''s **highest peacetime gallantry award**, equivalent in stature to the wartime Param Vir Chakra.

It is awarded for the **most conspicuous bravery or courage** displayed away from the battlefield, and was instituted in **1952**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00225', 'current-affairs-gk-bank', 'Awards & Honours', 3, 8, 'What are the Maha Vir Chakra and Vir Chakra?', 'The **Maha Vir Chakra** is India''s **second-highest wartime gallantry award**, and the **Vir Chakra** is the **third-highest**.

Both decorations, instituted in **1950**, rank below the Param Vir Chakra in order of precedence for valour shown in the presence of the enemy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00226', 'current-affairs-gk-bank', 'Awards & Honours', 3, 9, 'What are the Kirti Chakra and Shaurya Chakra?', 'The **Kirti Chakra** and **Shaurya Chakra** are India''s **second- and third-highest peacetime gallantry awards** respectively, ranking below the Ashoka Chakra.

Both were instituted in **1952** to recognise acts of bravery displayed away from active battle.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00227', 'current-affairs-gk-bank', 'Awards & Honours', 3, 10, 'What is the Jnanpith Award, and who was its first recipient?', 'The **Jnanpith Award** is one of India''s highest literary honours, instituted by the **Bharatiya Jnanpith** in **1961** and first conferred in **1965**.

Its first recipient was the Malayalam poet **G. Sankara Kurup**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00228', 'current-affairs-gk-bank', 'Awards & Honours', 3, 11, 'What is the Sahitya Akademi Award?', 'The **Sahitya Akademi Award** is a literary honour conferred annually by **India''s National Academy of Letters (Sahitya Akademi)**, instituted in **1954**.

It recognises outstanding literary works in **24 recognised Indian languages**, including English.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00229', 'current-affairs-gk-bank', 'Awards & Honours', 3, 12, 'When was the Nobel Prize established, and who established it?', 'The **Nobel Prize** was established according to the **will of Alfred Nobel**, a Swedish inventor and chemist best known for inventing **dynamite**.

The prizes were **first awarded in 1901**, five years after Nobel''s death in 1896.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00230', 'current-affairs-gk-bank', 'Awards & Honours', 3, 13, 'What are the original categories of the Nobel Prize?', 'The **original Nobel Prize categories**, as specified in Alfred Nobel''s will, are **Physics, Chemistry, Physiology or Medicine, Literature, and Peace**.

A sixth prize, the **Prize in Economic Sciences**, was added later by Sweden''s central bank and first awarded in **1969**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00231', 'current-affairs-gk-bank', 'Awards & Honours', 3, 14, 'In which city is the Nobel Peace Prize awarded, unlike the other Nobel Prizes?', 'Unlike the other Nobel Prizes, which are awarded in **Stockholm, Sweden**, the **Nobel Peace Prize** is awarded in **Oslo, Norway**.

This distinction was specified by Alfred Nobel himself in his will.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00232', 'current-affairs-gk-bank', 'Awards & Honours', 3, 15, 'What is the Dronacharya Award given for?', 'The **Dronacharya Award**, instituted in **1985**, is conferred for **excellence in sports coaching**.

It is named after **Dronacharya**, the legendary teacher of archery and warfare in the Mahabharata.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00233', 'current-affairs-gk-bank', 'Awards & Honours', 3, 16, 'What is the Arjuna Award given for?', 'The **Arjuna Award**, instituted in **1961**, is conferred for **consistently outstanding performance in sports** over a period of years.

It is named after **Arjuna**, the skilled archer-warrior of the Mahabharata.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00234', 'current-affairs-gk-bank', 'Awards & Honours', 3, 17, 'What is India''s highest sporting honour, and what was it previously called?', 'India''s highest sporting honour is the **Major Dhyan Chand Khel Ratna Award**.

It was originally instituted in **1991-92** as the **"Rajiv Gandhi Khel Ratna,"** and was renamed in **2021** after hockey legend Major Dhyan Chand.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00235', 'current-affairs-gk-bank', 'Awards & Honours', 3, 18, 'What is the Dadasaheb Phalke Award, and when was it instituted?', 'The **Dadasaheb Phalke Award** is India''s **highest award in the field of cinema**, instituted in **1969**.

It is named after **Dadasaheb Phalke**, widely regarded as the **"Father of Indian Cinema"** for producing India''s first full-length feature film, *Raja Harishchandra* (1913).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00236', 'current-affairs-gk-bank', 'Awards & Honours', 3, 19, 'When were the National Film Awards instituted in India?', 'India''s **National Film Awards** were instituted in **1954** by the Government of India.

They are presented annually to honour excellence in **Indian cinema** across multiple languages and categories.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00237', 'current-affairs-gk-bank', 'Awards & Honours', 3, 20, 'What is the Kalinga Prize, and what does it recognise?', 'The **Kalinga Prize**, instituted by **UNESCO in 1951**, recognises individuals for their exceptional contribution to the **popularisation of science** among the general public.

It was established following a donation by Indian industrialist and politician **Biju Patnaik**, and is named after the ancient kingdom of Kalinga.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00238', 'current-affairs-gk-bank', 'Awards & Honours', 3, 21, 'What is the Shanti Swarup Bhatnagar Prize?', 'The **Shanti Swarup Bhatnagar Prize** is India''s foremost award for **excellence in science and technology**, instituted in **1958** by the **Council of Scientific and Industrial Research (CSIR)**.

It is named after **Dr. Shanti Swarup Bhatnagar**, the founding director of CSIR.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00239', 'current-affairs-gk-bank', 'Awards & Honours', 3, 22, 'What is the Saraswati Samman, and who confers it?', 'The **Saraswati Samman** is a prestigious literary award instituted in **1991** by the **K. K. Birla Foundation**.

It is conferred annually for an outstanding literary work written in any of the **languages listed in the Eighth Schedule of the Indian Constitution**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00240', 'current-affairs-gk-bank', 'Awards & Honours', 3, 23, 'What is the Vyas Samman, and for which language is it awarded?', 'The **Vyas Samman** is a literary award instituted by the **K. K. Birla Foundation**, given annually for an outstanding literary work written in **Hindi**.

It was first awarded in **1991**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00241', 'current-affairs-gk-bank', 'Awards & Honours', 3, 24, 'What is the Moortidevi Award, and which organisation confers it?', 'The **Moortidevi Award** is an annual literary award conferred by the **Bharatiya Jnanpith**, instituted in **1983**.

It recognises literary works that reflect **Indian thought, culture, and philosophy**, and may be awarded across any Indian language, including English.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00242', 'current-affairs-gk-bank', 'Awards & Honours', 3, 25, 'What is the Gandhi Peace Prize, and when was it instituted?', 'The **International Gandhi Peace Prize** was instituted by the **Government of India in 1995**, marking Mahatma Gandhi''s 125th birth anniversary.

It is awarded annually for contributions towards **social, economic, and political transformation through non-violence** and other Gandhian methods.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00243', 'current-affairs-gk-bank', 'Awards & Honours', 3, 26, 'What is the Fields Medal, and why is it often called the "Nobel Prize of Mathematics"?', 'The **Fields Medal** is one of the highest honours in mathematics, awarded once every **four years** to mathematicians **under the age of 40**.

It is often called the **"Nobel Prize of Mathematics"** because no Nobel Prize exists for the field; the medal was instituted in **1936**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00244', 'current-affairs-gk-bank', 'Awards & Honours', 3, 27, 'What is the Abel Prize, and why was it created?', 'The **Abel Prize** is a prestigious mathematics award, instituted by the **Norwegian government in 2002** and first awarded in **2003**.

It was created partly to serve as a mathematics-specific equivalent to the Nobel Prize, which has no category for mathematics, and is named after Norwegian mathematician **Niels Henrik Abel**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00245', 'current-affairs-gk-bank', 'Awards & Honours', 3, 28, 'What is the Pulitzer Prize, and who established it?', 'The **Pulitzer Prize** is a prestigious American award recognising achievements in **journalism, literature, and musical composition**.

It was established through the will of publisher **Joseph Pulitzer** and first awarded in **1917**, administered by **Columbia University**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00246', 'current-affairs-gk-bank', 'Awards & Honours', 3, 29, 'Who was the first Indian-origin recipient of the Pulitzer Prize?', '**Gobind Behari Lal**, an Indian-American journalist, became the **first person of Indian origin to win a Pulitzer Prize**, in **1937**, in the Reporting category.

He was honoured for his science journalism covering a major American science conference.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00247', 'current-affairs-gk-bank', 'Awards & Honours', 3, 30, 'What is the Booker Prize, and when was it established?', 'The **Booker Prize** (formerly the Man Booker Prize) is a leading literary award for the **best novel written in English**, established in **1969** in the United Kingdom.

An **International Booker Prize**, for works translated into English, was introduced separately in **2005**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00248', 'current-affairs-gk-bank', 'Awards & Honours', 3, 31, 'What is the Ramon Magsaysay Award, and after whom is it named?', 'The **Ramon Magsaysay Award** is often referred to as **"Asia''s Nobel Prize."**

It was instituted in **1957** and is named after **Ramon Magsaysay**, a former President of the Philippines, recognising greatness of spirit in public service across Asia.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00249', 'current-affairs-gk-bank', 'Awards & Honours', 3, 32, 'What is the Templeton Prize awarded for?', 'The **Templeton Prize**, instituted in **1972** by investor **Sir John Templeton**, honours individuals for **exceptional contributions affirming the spiritual dimension of life**, often spanning science, philosophy, or theology.

It is sometimes noted for carrying a monetary value **deliberately set higher than the Nobel Prize**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00250', 'current-affairs-gk-bank', 'Awards & Honours', 3, 33, 'What is the Right Livelihood Award often called, and when was it instituted?', 'The **Right Livelihood Award** is often referred to as the **"Alternative Nobel Prize."**

It was instituted in **1980** by Swedish-German philanthropist **Jakob von Uexkull**, honouring work addressing the world''s most pressing challenges.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00251', 'current-affairs-gk-bank', 'Awards & Honours', 3, 34, 'What is the Pritzker Prize, and what field does it honour?', 'The **Pritzker Architecture Prize** is often described as the **"Nobel Prize of Architecture."**

It was established in **1979** by the Pritzker family of Chicago and is awarded annually to a living architect for significant contributions to the field.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00252', 'current-affairs-gk-bank', 'Awards & Honours', 3, 35, 'What is the Turing Award, and which field does it honour?', 'The **Turing Award** is often described as the **"Nobel Prize of Computing."**

Instituted in **1966** by the **Association for Computing Machinery (ACM)**, it honours major contributions to **computer science**, and is named after British mathematician **Alan Turing**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00253', 'current-affairs-gk-bank', 'Awards & Honours', 3, 36, 'What is the National Bravery Award for children, and which organisation administers it?', 'The **National Bravery Award** is conferred on children who display **exceptional courage** in difficult circumstances.

It was instituted in **1957** and is administered by the **Indian Council for Child Welfare (ICCW)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00254', 'current-affairs-gk-bank', 'Awards & Honours', 3, 37, 'What is the Subhash Chandra Bose Aapda Prabandhan Puraskar?', 'The **Subhash Chandra Bose Aapda Prabandhan Puraskar** is an award instituted in **2019** by the Government of India.

It recognises **outstanding contributions in the field of disaster management**, given to individuals and organisations each year on **23 January**, Netaji''s birth anniversary.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00255', 'current-affairs-gk-bank', 'Awards & Honours', 3, 38, 'What is the Rashtriya Khel Protsahan Puraskar?', 'The **Rashtriya Khel Protsahan Puraskar**, instituted in **2009**, is conferred on **corporate entities and organisations** (rather than individual athletes) for their contribution to the **promotion and development of sports** in India.

It is given alongside the National Sports Awards each year.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00256', 'current-affairs-gk-bank', 'Awards & Honours', 3, 39, 'What is the Nari Shakti Puraskar?', 'The **Nari Shakti Puraskar** is India''s highest civilian award recognising contributions towards the **empowerment of women**.

It is conferred annually by the **Ministry of Women and Child Development**, typically presented on **International Women''s Day (8 March)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00257', 'current-affairs-gk-bank', 'Awards & Honours', 3, 40, 'Who was the first person to receive the Bharat Ratna posthumously?', '**Lal Bahadur Shastri**, India''s second Prime Minister, was the **first person to be awarded the Bharat Ratna posthumously**, in **1966**.

He was honoured for his leadership, including his role during the **1965 Indo-Pakistani War** and his famous slogan **"Jai Jawan Jai Kisan."**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00258', 'current-affairs-gk-bank', 'Awards & Honours', 3, 41, 'What are the Academy Awards (Oscars), and which body presents them?', 'The **Academy Awards**, popularly known as the **Oscars**, are presented annually by the **Academy of Motion Picture Arts and Sciences (AMPAS)**.

The awards were **first given out in 1929**, honouring excellence in cinematic achievement.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00259', 'current-affairs-gk-bank', 'Awards & Honours', 3, 42, 'What are the Grammy Awards, and which field do they honour?', 'The **Grammy Awards** honour achievements in the **music industry**, presented annually by the **Recording Academy** in the United States.

The awards were **first held in 1959**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00260', 'current-affairs-gk-bank', 'Awards & Honours', 3, 43, 'What is the Legion of Honour, and which country awards it?', 'The **Legion of Honour (Légion d''honneur)** is **France''s highest order of merit**, both military and civilian.

It was **established by Napoleon Bonaparte in 1802** and remains France''s most prestigious state decoration.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00261', 'current-affairs-gk-bank', 'Awards & Honours', 3, 44, 'What is the Victoria Cross, and what does it recognise?', 'The **Victoria Cross** is the **highest military decoration awarded for valour** in the armed forces of the United Kingdom and various Commonwealth nations.

It was **instituted in 1856** by Queen Victoria, following the Crimean War.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00262', 'current-affairs-gk-bank', 'Awards & Honours', 3, 45, 'What is the Presidential Medal of Freedom?', 'The **Presidential Medal of Freedom** is the **highest civilian award in the United States**.

It recognises individuals who have made **exceptional contributions to the security or national interests of the United States, world peace, or cultural endeavours**, and was established in its modern form in **1963**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00263', 'current-affairs-gk-bank', 'Awards & Honours', 3, 46, 'What distinguishes the Param Vir Chakra from the Ashoka Chakra?', 'The **Param Vir Chakra** is awarded for **extraordinary valour displayed in the presence of the enemy** (wartime gallantry), while the **Ashoka Chakra** honours equally extraordinary courage shown **away from the battlefield** (peacetime gallantry).

Both are considered India''s **highest-ranking decorations** within their respective categories.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00264', 'current-affairs-gk-bank', 'Awards & Honours', 3, 47, 'What is the Tagore Award for Cultural Harmony?', 'The **Tagore Award for Cultural Harmony** was instituted by the **Government of India in 2012**, marking the **150th birth anniversary of Rabindranath Tagore**.

It recognises contributions towards **promoting cultural harmony and intercultural dialogue and understanding**, open to recipients from any country.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00265', 'current-affairs-gk-bank', 'Awards & Honours', 3, 48, 'What is the Indira Gandhi Prize for Peace, Disarmament and Development?', 'The **Indira Gandhi Prize** was instituted in **1986** by the **Indira Gandhi Memorial Trust**.

It is awarded annually in recognition of **creative efforts towards peace, disarmament, and development**, open to individuals and institutions worldwide.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00266', 'current-affairs-gk-bank', 'Awards & Honours', 3, 49, 'How many languages does the Sahitya Akademi officially recognise for its awards?', 'The **Sahitya Akademi** recognises literary works in **24 languages**, including the languages listed in the **Eighth Schedule of the Constitution**, as well as **English**.

The award carries a citation and a cash prize, presented annually.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00267', 'current-affairs-gk-bank', 'Awards & Honours', 3, 50, 'What does winning a "Grand Slam" mean in the context of literary and academic prizes, broadly speaking, such as EGOT?', '"**EGOT**" refers to winning all four major American entertainment awards: the **Emmy (television), Grammy (music), Oscar (film), and Tony (theatre)**.

Only a small number of individuals in entertainment history have achieved this combination across their careers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00268', 'current-affairs-gk-bank', 'Awards & Honours', 3, 51, 'What is the significance of the term "Nobel Laureate"?', 'A **"Nobel Laureate"** refers to any individual or organisation that has been awarded a **Nobel Prize**, in recognition of outstanding achievement in their respective field.

The term "laureate" derives from the ancient tradition of **crowning victors with a laurel wreath**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00269', 'current-affairs-gk-bank', 'Awards & Honours', 3, 52, 'What distinguishes the Param Vir Chakra, Maha Vir Chakra, and Vir Chakra in order of precedence?', 'In order of precedence for **wartime gallantry**, the **Param Vir Chakra** ranks highest, followed by the **Maha Vir Chakra**, and then the **Vir Chakra**.

All three decorations were instituted by the Government of India in **1950**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00270', 'current-affairs-gk-bank', 'Awards & Honours', 3, 53, 'What is the Gallantry Awards'' typical day of announcement in India?', 'India''s **gallantry awards**, including the Param Vir Chakra and Ashoka Chakra, are typically announced around **Republic Day (26 January)** each year.

They may also be announced around **Independence Day (15 August)** in some years, depending on operational citations.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00271', 'current-affairs-gk-bank', 'Awards & Honours', 3, 54, 'What is the Jnanpith Award''s significance among Indian literary honours?', 'The **Jnanpith Award** is widely regarded as **India''s highest literary honour**.

Unlike the Sahitya Akademi Award, which is given language-wise each year, the Jnanpith Award recognises a **single writer''s entire body of work**, chosen from among all recognised Indian languages.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00272', 'current-affairs-gk-bank', 'Awards & Honours', 3, 55, 'What was the first scientific field in which an Indian won a Nobel Prize, and who was the recipient?', 'The first scientific Nobel Prize won by an Indian was in **Physics**, awarded to **C. V. Raman in 1930** for his discovery of the **"Raman Effect"**, concerning the scattering of light.

He conducted the prize-winning research entirely within India, at institutions in Kolkata.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00273', 'current-affairs-gk-bank', 'Awards & Honours', 3, 56, 'Who was the first Indian to be honoured with a Nobel Prize, in any category?', '**Rabindranath Tagore** was the **first Indian (and first Asian)** to be awarded a Nobel Prize, winning the **Nobel Prize in Literature in 1913** for his collection *Gitanjali*.

This remains a landmark moment in Indian intellectual and cultural history.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00274', 'current-affairs-gk-bank', 'Awards & Honours', 3, 57, 'What is the significance of the Param Vishisht Seva Medal in the Indian armed forces?', 'The **Param Vishisht Seva Medal (PVSM)** is one of India''s highest **distinguished service decorations**, awarded for **exceptionally distinguished service of the most exceptional order**.

It is typically awarded to senior armed forces officers and was instituted in **1960**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00275', 'current-affairs-gk-bank', 'Awards & Honours', 3, 58, 'What is the Bhatnagar Prize''s eligibility age limit, and why is it significant?', 'The **Shanti Swarup Bhatnagar Prize** has traditionally been awarded to Indian scientists **below the age of 45** (at the time of the award).

This age criterion is designed to recognise and encourage **early and mid-career excellence** in scientific research.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00276', 'current-affairs-gk-bank', 'Awards & Honours', 3, 59, 'What is the significance of the term "Posthumous Award" as used with gallantry honours?', 'A **"posthumous award"** is one conferred **after the recipient''s death**, often in recognition of valour shown in the final act of their service or sacrifice.

Many of India''s **Param Vir Chakra** recipients, including the very first, Major Somnath Sharma, received the honour posthumously.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00277', 'current-affairs-gk-bank', 'Awards & Honours', 3, 60, 'What distinguishes the Padma Vibhushan from the Padma Bhushan and Padma Shri?', 'The **Padma Vibhushan** is the **second-highest civilian award** in India, ranking above the **Padma Bhushan** (third-highest) and **Padma Shri** (fourth-highest).

All three were instituted together in **1954**, forming the structure of the Padma Awards.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00278', 'current-affairs-gk-bank', 'Awards & Honours', 3, 61, 'What award recognises excellence in classical and folk arts performance training in India?', 'The **Sangeet Natak Akademi Award**, India''s highest recognition in the **performing arts** (music, dance, and drama), is conferred annually by the **Sangeet Natak Akademi**, India''s National Academy for Music, Dance, and Drama, established in **1952**.

It is often referred to as the **"Akademi Award."**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00279', 'current-affairs-gk-bank', 'Awards & Honours', 3, 62, 'What award does the Lalit Kala Akademi confer, and in which field?', 'The **Lalit Kala Akademi**, India''s National Academy of Fine Arts established in **1954**, confers the **Lalit Kala Akademi Award** (Akademi Ratna and Akademi Puraskar) for excellence in the **visual arts**, including painting, sculpture, and graphics.

It functions alongside the Sahitya Akademi (literature) and Sangeet Natak Akademi (performing arts) as one of India''s three central cultural academies.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00280', 'current-affairs-gk-bank', 'Awards & Honours', 3, 63, 'Who designed India''s Param Vir Chakra and several other gallantry medals?', 'India''s **Param Vir Chakra**, along with the **Ashoka Chakra, Maha Vir Chakra, and Vir Chakra**, was designed by **Savitri Khanolkar**, a Swiss-born Indian artist.

She was commissioned by the Indian government shortly after independence to design the country''s new system of military honours.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00281', 'current-affairs-gk-bank', 'Awards & Honours', 3, 64, 'What is the World Food Prize, and after whom was it inspired?', 'The **World Food Prize** was established in **1986** by **Norman Borlaug**, the agricultural scientist known as the father of the **Green Revolution**.

It recognises individuals who have made outstanding contributions to **improving the quality, quantity, or availability of food** in the world.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00282', 'current-affairs-gk-bank', 'Awards & Honours', 3, 65, 'What is the Sakharov Prize, and which body awards it?', 'The **Sakharov Prize for Freedom of Thought** is awarded annually by the **European Parliament**, instituted in **1988**.

It is named after Soviet physicist and dissident **Andrei Sakharov** and honours individuals or organisations defending **human rights and fundamental freedoms**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00283', 'current-affairs-gk-bank', 'Awards & Honours', 3, 66, 'What is the Ramnath Goenka Award for Excellence in Journalism?', 'The **Ramnath Goenka Award for Excellence in Journalism** was instituted in **1992** by the **Indian Express Group**.

It is named after **Ramnath Goenka**, founder of The Indian Express, and recognises outstanding work across categories of print, broadcast, and digital journalism in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00284', 'current-affairs-gk-bank', 'Awards & Honours', 3, 67, 'What is the Ati Vishisht Seva Medal (AVSM)?', 'The **Ati Vishisht Seva Medal (AVSM)** is a **distinguished service decoration** awarded to officers of the Indian armed forces for **distinguished service of an exceptional order**.

It was instituted in **1960**, ranking below the Param Vishisht Seva Medal in order of precedence among service decorations.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00285', 'current-affairs-gk-bank', 'Awards & Honours', 3, 68, 'What is the Sarvottam Jeevan Raksha Padak?', 'The **Sarvottam Jeevan Raksha Padak** is the **highest award in India''s Jeevan Raksha Padak series**, instituted in **1961**.

It is conferred for **conspicuous courage in rescuing a person from life-threatening situations** such as drowning, fire, or accidents.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00286', 'current-affairs-gk-bank', 'Awards & Honours', 3, 69, 'What is the official name of the Nobel Prize in Economics, and why does it differ from the others?', 'The Nobel Prize in Economics is officially called the **"Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel."**

It differs from the original five Nobel Prizes because it was established separately by **Sweden''s central bank (Sveriges Riksbank) in 1968**, and was first awarded in **1969**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00287', 'current-affairs-gk-bank', 'Awards & Honours', 3, 70, 'What is the Order of the Garter, and which country awards it?', 'The **Order of the Garter** is the **oldest and most senior order of chivalry in the United Kingdom**, established by **King Edward III in 1348**.

Membership is strictly limited, and it is conferred at the personal discretion of the British monarch.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00288', 'current-affairs-gk-bank', 'Science & Technology', 4, 0, 'When was the Indian Space Research Organisation (ISRO) founded, and who is considered its founder?', '**ISRO (Indian Space Research Organisation)** was founded in **1969**, evolving from the earlier **Indian National Committee for Space Research (INCOSPAR)**, established in 1962.

**Dr. Vikram Sarabhai** is widely regarded as the **"Father of the Indian Space Programme."**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00289', 'current-affairs-gk-bank', 'Science & Technology', 4, 1, 'Where is the headquarters of ISRO located?', '**ISRO''s headquarters** is located in **Bengaluru, Karnataka**.

It functions under the **Department of Space**, which reports directly to the **Prime Minister of India**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00290', 'current-affairs-gk-bank', 'Science & Technology', 4, 2, 'What was significant about India''s first sounding rocket launch?', 'India''s **first sounding rocket** was launched from **Thumba Equatorial Rocket Launching Station (TERLS)** in Kerala, on **21 November 1963**.

This launch marked the **beginning of India''s space research programme**, predating the formal establishment of ISRO.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00291', 'current-affairs-gk-bank', 'Science & Technology', 4, 3, 'What was significant about Chandrayaan-1, and when was it launched?', '**Chandrayaan-1**, launched by ISRO in **2008**, was **India''s first lunar exploration mission**.

It is credited with providing crucial evidence confirming the **presence of water molecules on the Moon''s surface**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00292', 'current-affairs-gk-bank', 'Science & Technology', 4, 4, 'What was significant about India''s Mars Orbiter Mission (Mangalyaan)?', 'The **Mars Orbiter Mission (Mangalyaan)** was launched by ISRO in **2013** and successfully entered Mars orbit in **2014**.

India became the **first country to reach Mars orbit in its very first attempt**, and did so at a remarkably low cost compared to other space agencies.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00293', 'current-affairs-gk-bank', 'Science & Technology', 4, 5, 'What made Chandrayaan-3''s landing historically significant for India?', '**Chandrayaan-3**, launched in **2023**, successfully soft-landed its **Vikram lander** near the **lunar south pole** in August of that year.

This made India the **fourth country to achieve a soft lunar landing**, and the **first in the world to land near the Moon''s south polar region**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00294', 'current-affairs-gk-bank', 'Science & Technology', 4, 6, 'What is the PSLV, and what role does it play in India''s space programme?', 'The **PSLV (Polar Satellite Launch Vehicle)** is ISRO''s reliable workhorse launch vehicle, first successfully flown in **1994**.

It has been used to launch numerous satellites into **polar and sun-synchronous orbits**, including missions like Chandrayaan-1 and the Mars Orbiter Mission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00295', 'current-affairs-gk-bank', 'Science & Technology', 4, 7, 'What is the GSLV, and how does it differ from the PSLV?', 'The **GSLV (Geosynchronous Satellite Launch Vehicle)** is designed to place **heavier satellites into geostationary transfer orbit**, unlike the PSLV, which is optimised for polar orbits.

It uses a **cryogenic upper stage**, technology that India indigenously developed after initial international restrictions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00296', 'current-affairs-gk-bank', 'Science & Technology', 4, 8, 'Who is regarded as the father of India''s nuclear programme?', '**Dr. Homi J. Bhabha** is regarded as the **"Father of the Indian Nuclear Programme."**

He founded the **Tata Institute of Fundamental Research (TIFR)** in **1945** and later established the **Atomic Energy Commission of India** in **1948**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00297', 'current-affairs-gk-bank', 'Science & Technology', 4, 9, 'What is the Bhabha Atomic Research Centre (BARC)?', 'The **Bhabha Atomic Research Centre (BARC)**, located in **Trombay, Mumbai**, is India''s premier nuclear research facility.

It was established in **1954** as the **Atomic Energy Establishment, Trombay (AEET)**, and was renamed in **1967** in honour of Dr. Homi Bhabha.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00298', 'current-affairs-gk-bank', 'Science & Technology', 4, 10, 'When did India conduct its first nuclear test, and what was it codenamed?', 'India conducted its **first nuclear test**, codenamed **"Smiling Buddha,"** on **18 May 1974** at the **Pokhran test range** in Rajasthan.

It was described by India at the time as a **"peaceful nuclear explosion."**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00299', 'current-affairs-gk-bank', 'Science & Technology', 4, 11, 'When did India conduct its second round of nuclear tests, known as Pokhran-II?', 'India conducted a series of nuclear tests known as **"Pokhran-II"** in **May 1998**, at the Pokhran range in Rajasthan.

These tests led India to formally declare itself a **nuclear weapons state**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00300', 'current-affairs-gk-bank', 'Science & Technology', 4, 12, 'When was the Council of Scientific and Industrial Research (CSIR) established?', 'The **Council of Scientific and Industrial Research (CSIR)** was established in **1942**.

It is India''s **largest research and development organisation**, operating a network of national laboratories across diverse scientific fields.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00301', 'current-affairs-gk-bank', 'Science & Technology', 4, 13, 'When was the Defence Research and Development Organisation (DRDO) established?', 'The **Defence Research and Development Organisation (DRDO)** was established in **1958**, through the merger of existing defence science organisations.

It operates under the **Ministry of Defence** and is responsible for developing military technology for the Indian armed forces.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00302', 'current-affairs-gk-bank', 'Science & Technology', 4, 14, 'Which was the first Indian Institute of Technology (IIT) to be established?', '**IIT Kharagpur**, established in **1951**, was the **first of the Indian Institutes of Technology**.

It was set up based on the recommendations of the **Sarkar Committee**, aimed at creating institutions of higher technical education.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00303', 'current-affairs-gk-bank', 'Science & Technology', 4, 15, 'When was the Indian Institute of Science (IISc) founded, and by whom?', 'The **Indian Institute of Science (IISc)**, located in Bengaluru, was founded in **1909**.

It was established with a generous endowment from industrialist **Jamsetji Tata**, and remains one of India''s premier research institutions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00304', 'current-affairs-gk-bank', 'Science & Technology', 4, 16, 'What are the seven base units of the International System of Units (SI)?', 'The seven **SI base units** are the **metre (length), kilogram (mass), second (time), ampere (electric current), kelvin (temperature), mole (amount of substance), and candela (luminous intensity)**.

All other physical units are derived as combinations of these seven base units.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00305', 'current-affairs-gk-bank', 'Science & Technology', 4, 17, 'Who devised the modern Periodic Table of elements, and when?', 'The **Periodic Table** in its recognisable modern form was devised by Russian chemist **Dmitri Mendeleev** in **1869**.

He arranged elements by **atomic weight** and famously left gaps for elements yet to be discovered, correctly predicting some of their properties.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00306', 'current-affairs-gk-bank', 'Science & Technology', 4, 18, 'Who formulated the three laws of motion, and in which work?', '**Sir Isaac Newton** formulated the **three laws of motion**, published in his landmark 1687 work, *"Philosophiæ Naturalis Principia Mathematica."*

These laws form the foundation of **classical mechanics**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00307', 'current-affairs-gk-bank', 'Science & Technology', 4, 19, 'Who proposed the Theory of Relativity, and what are its two main forms?', '**Albert Einstein** proposed the **Theory of Relativity**, consisting of the **Special Theory of Relativity (1905)** and the **General Theory of Relativity (1915)**.

The theory fundamentally reshaped understanding of **space, time, and gravity**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00308', 'current-affairs-gk-bank', 'Science & Technology', 4, 20, 'Who discovered the double-helix structure of DNA, and when?', 'The **double-helix structure of DNA** was described by **James Watson and Francis Crick in 1953**, building on crucial X-ray diffraction data from **Rosalind Franklin and Maurice Wilkins**.

Watson, Crick, and Wilkins were jointly awarded the **Nobel Prize in Physiology or Medicine in 1962** for this discovery.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00309', 'current-affairs-gk-bank', 'Science & Technology', 4, 21, 'Who proposed the Theory of Evolution by natural selection?', '**Charles Darwin** proposed the **Theory of Evolution by Natural Selection**, detailed in his **1859** book *"On the Origin of Species."*

The theory explains how species evolve over generations through the **survival and reproduction of better-adapted individuals**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00310', 'current-affairs-gk-bank', 'Science & Technology', 4, 22, 'Who is credited with inventing the telephone?', '**Alexander Graham Bell** is credited with inventing the **telephone**, receiving a patent for the device in **1876**.

It revolutionised long-distance communication and laid the foundation for the modern telecommunications industry.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00311', 'current-affairs-gk-bank', 'Science & Technology', 4, 23, 'Who is credited with inventing the World Wide Web?', '**Tim Berners-Lee**, a British computer scientist, invented the **World Wide Web in 1989** while working at **CERN**.

His invention made the internet accessible to the general public through browsers and hyperlinked documents.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00312', 'current-affairs-gk-bank', 'Science & Technology', 4, 24, 'Who developed the first commercially practical electric light bulb?', '**Thomas Edison** developed the first **commercially practical incandescent light bulb**, patenting his design in **1879**.

Earlier inventors had experimented with incandescent lighting, but Edison''s version was the first to achieve long-lasting, practical use.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00313', 'current-affairs-gk-bank', 'Science & Technology', 4, 25, 'Who discovered penicillin, and when?', '**Alexander Fleming** discovered **penicillin in 1928**, observing that a mould had killed bacteria in a petri dish he had left uncovered.

This discovery is regarded as the beginning of the **modern age of antibiotics**, and Fleming shared the **1945 Nobel Prize in Physiology or Medicine** for it.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00314', 'current-affairs-gk-bank', 'Science & Technology', 4, 26, 'Who discovered the ABO blood group system?', '**Karl Landsteiner**, an Austrian biologist, discovered the **ABO blood group system in 1901**.

His work earned him the **Nobel Prize in Physiology or Medicine in 1930**, and remains foundational to safe blood transfusion practices.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00315', 'current-affairs-gk-bank', 'Science & Technology', 4, 27, 'Who is regarded as the "father of the computer," and why?', '**Charles Babbage** is regarded as the **"father of the computer"** for designing the **Analytical Engine** in the 1830s, a mechanical general-purpose computer concept, though it was never completed in his lifetime.

**Ada Lovelace** is credited with writing what is considered the **first computer algorithm**, intended for this machine.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00316', 'current-affairs-gk-bank', 'Science & Technology', 4, 28, 'Who is considered the father of modern computer science and artificial intelligence?', '**Alan Turing**, a British mathematician, is considered a father of **modern computer science and artificial intelligence**.

He developed the concept of the **"Turing Machine"** and the **Turing Test**, and played a key role in codebreaking during the Second World War.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00317', 'current-affairs-gk-bank', 'Science & Technology', 4, 29, 'Who developed the smallpox vaccine, considered the first vaccine?', '**Edward Jenner**, an English physician, developed the **smallpox vaccine in 1796**, using material from cowpox lesions.

His work laid the foundation for the field of **immunology** and the broader practice of vaccination.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00318', 'current-affairs-gk-bank', 'Science & Technology', 4, 30, 'With whom is India''s "Green Revolution" most closely associated?', 'India''s **Green Revolution** of the 1960s is most closely associated with agricultural scientist **M. S. Swaminathan**, often called the **"Father of the Green Revolution in India."**

It involved the introduction of **high-yielding variety (HYV) seeds**, modern irrigation, and fertilisers, significantly boosting food grain production.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00319', 'current-affairs-gk-bank', 'Science & Technology', 4, 31, 'Who is known globally as the "Father of the Green Revolution"?', '**Norman Borlaug**, an American agronomist, is known globally as the **"Father of the Green Revolution."**

He developed high-yielding, disease-resistant wheat varieties and was awarded the **Nobel Peace Prize in 1970** for his contribution to global food security.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00320', 'current-affairs-gk-bank', 'Science & Technology', 4, 32, 'With whom is India''s "White Revolution" associated, and what did it achieve?', 'India''s **"White Revolution"** is associated with **Dr. Verghese Kurien**, often called the **"Father of the White Revolution."**

It was carried out through **"Operation Flood,"** launched in **1970**, which transformed India into one of the **world''s largest milk producers**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00321', 'current-affairs-gk-bank', 'Science & Technology', 4, 33, 'What is CERN, and what is it best known for operating?', '**CERN (European Organization for Nuclear Research)**, founded in **1954**, is headquartered near **Geneva, Switzerland**.

It operates the **Large Hadron Collider (LHC)**, the world''s largest and most powerful particle accelerator, used to study fundamental particle physics.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00322', 'current-affairs-gk-bank', 'Science & Technology', 4, 34, 'When was NASA established, and in which country?', '**NASA (National Aeronautics and Space Administration)** was established in **1958** in the **United States**.

It was created partly in response to the **Soviet Union''s launch of Sputnik**, and has since led numerous landmark space missions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00323', 'current-affairs-gk-bank', 'Science & Technology', 4, 35, 'Who was the first human to land on the Moon, and in which mission?', '**Neil Armstrong** became the **first human to walk on the Moon**, during NASA''s **Apollo 11 mission on 20 July 1969**.

He was accompanied by **Buzz Aldrin**, while **Michael Collins** remained in lunar orbit aboard the command module.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00324', 'current-affairs-gk-bank', 'Science & Technology', 4, 36, 'What was Sputnik 1, and why is it significant?', '**Sputnik 1**, launched by the **Soviet Union in 1957**, was the **world''s first artificial satellite**.

Its launch marked the **beginning of the Space Age** and triggered the Cold War-era space race between the USSR and the USA.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00325', 'current-affairs-gk-bank', 'Science & Technology', 4, 37, 'Who was the first human to travel into space?', '**Yuri Gagarin**, a Soviet cosmonaut, became the **first human to travel into space**, orbiting the Earth aboard **Vostok 1 on 12 April 1961**.

This achievement marked a major milestone in the history of human spaceflight.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00326', 'current-affairs-gk-bank', 'Science & Technology', 4, 38, 'What was Laika, and what was her significance in space history?', '**Laika** was a dog sent into orbit aboard the Soviet spacecraft **Sputnik 2** in **1957**.

She became the **first living creature to orbit the Earth**, providing early data on the effects of spaceflight on living organisms.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00327', 'current-affairs-gk-bank', 'Science & Technology', 4, 39, 'What does the pH scale measure, and who devised it?', 'The **pH scale** measures the **acidity or alkalinity of a solution**, ranging typically from **0 to 14**, with 7 being neutral.

It was devised by Danish chemist **Søren Sørensen in 1909**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00328', 'current-affairs-gk-bank', 'Science & Technology', 4, 40, 'Which is considered the hardest naturally occurring substance?', '**Diamond**, a crystalline form of carbon, is considered the **hardest naturally occurring substance** on Earth.

Its hardness arises from the **strong covalent bonding** between carbon atoms in its crystal lattice structure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00329', 'current-affairs-gk-bank', 'Science & Technology', 4, 41, 'Which metal is known as the lightest of all metals?', '**Lithium** is known as the **lightest metal**, with a very low density compared to other metals.

It is widely used today in **rechargeable lithium-ion batteries**, found in electronics and electric vehicles.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00330', 'current-affairs-gk-bank', 'Science & Technology', 4, 42, 'Approximately what is the speed of light in a vacuum?', 'The **speed of light in a vacuum** is approximately **3 × 10⁸ metres per second** (about 299,792 kilometres per second).

This value, often denoted by the symbol **"c,"** is a fundamental constant in physics, central to Einstein''s theory of relativity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00331', 'current-affairs-gk-bank', 'Science & Technology', 4, 43, 'Who formulated the laws of planetary motion?', '**Johannes Kepler**, a German astronomer, formulated the **three laws of planetary motion** in the early 17th century.

His laws describe how planets move in **elliptical orbits** around the Sun, laying crucial groundwork for Newton''s later theory of gravitation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00332', 'current-affairs-gk-bank', 'Science & Technology', 4, 44, 'Who proposed the heliocentric model of the solar system?', '**Nicolaus Copernicus**, a Polish astronomer, proposed the **heliocentric model**, which placed the **Sun at the centre of the solar system**, in his 1543 work *"De revolutionibus orbium coelestium."*

This challenged the long-held geocentric view that Earth was the centre of the universe.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00333', 'current-affairs-gk-bank', 'Science & Technology', 4, 45, 'Who discovered X-rays, and when?', '**Wilhelm Röntgen**, a German physicist, discovered **X-rays in 1895**.

He was awarded the **first-ever Nobel Prize in Physics, in 1901**, for this discovery.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00334', 'current-affairs-gk-bank', 'Science & Technology', 4, 46, 'Who discovered radioactivity, and who further advanced its study?', '**Henri Becquerel** discovered **radioactivity in 1896**, observing that uranium salts emitted radiation.

**Marie Curie**, along with her husband **Pierre Curie**, extensively studied this phenomenon and discovered the elements **polonium and radium**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00335', 'current-affairs-gk-bank', 'Science & Technology', 4, 47, 'Who was the first person to win Nobel Prizes in two different scientific fields?', '**Marie Curie** was the **first person to win Nobel Prizes in two different fields** — **Physics (1903, shared)** and **Chemistry (1911)**.

She remains the only woman to have won the Nobel Prize in two different scientific disciplines.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00336', 'current-affairs-gk-bank', 'Science & Technology', 4, 48, 'Who is credited with inventing dynamite?', '**Alfred Nobel**, a Swedish chemist and engineer, invented **dynamite in 1867**.

His fortune from this and related inventions later funded the establishment of the **Nobel Prizes**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00337', 'current-affairs-gk-bank', 'Science & Technology', 4, 49, 'What is the significance of C-DAC and the PARAM supercomputer series in India?', '**C-DAC (Centre for Development of Advanced Computing)** was established in **1988** to develop indigenous supercomputing capability.

It produced India''s first supercomputer, **PARAM 8000**, in **1991**, following restrictions on India''s access to foreign supercomputing technology.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00338', 'current-affairs-gk-bank', 'Science & Technology', 4, 50, 'What is NavIC, and which agency operates it?', '**NavIC (Navigation with Indian Constellation)**, formerly known as **IRNSS**, is India''s **indigenous satellite navigation system**, developed and operated by **ISRO**.

It provides accurate position information over **India and the surrounding region**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00339', 'current-affairs-gk-bank', 'Science & Technology', 4, 51, 'What is GAGAN, and which agencies jointly developed it?', '**GAGAN (GPS Aided Geo Augmented Navigation)** is a satellite-based augmentation system jointly developed by **ISRO and the Airports Authority of India (AAI)**.

It improves the accuracy of satellite navigation, particularly for **civil aviation** over Indian airspace.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00340', 'current-affairs-gk-bank', 'Science & Technology', 4, 52, 'What was ARPANET, and why is it significant?', '**ARPANET**, developed by the **US Department of Defense** and first operational in **1969**, is widely regarded as the **precursor to the modern Internet**.

It pioneered the use of **packet-switching** technology for data communication between computers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00341', 'current-affairs-gk-bank', 'Science & Technology', 4, 53, 'Which vitamin''s deficiency causes scurvy?', 'A deficiency of **Vitamin C (ascorbic acid)** causes **scurvy**, a disease characterised by weakness, gum disease, and skin problems.

Historically, scurvy was common among sailors on long voyages before the link to **fresh fruits and vegetables** was understood.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00342', 'current-affairs-gk-bank', 'Science & Technology', 4, 54, 'Which vitamin''s deficiency causes night blindness?', 'A deficiency of **Vitamin A** causes **night blindness**, a condition that impairs vision in low-light conditions.

Vitamin A is essential for maintaining the health of the **retina**, particularly the rod cells responsible for vision in dim light.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00343', 'current-affairs-gk-bank', 'Science & Technology', 4, 55, 'Which blood group is known as the "universal donor" and which as the "universal recipient"?', '**O-negative blood** is known as the **"universal donor"** group, as it can generally be given to patients of any blood type in emergencies.

**AB-positive blood** is known as the **"universal recipient"** group, as individuals with this type can generally receive blood from any donor group.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00344', 'current-affairs-gk-bank', 'Science & Technology', 4, 56, 'What is the SI unit of force, and after whom is it named?', 'The **SI unit of force** is the **Newton (N)**, named after **Sir Isaac Newton**.

One Newton is defined as the force required to accelerate a mass of **one kilogram at one metre per second squared**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00345', 'current-affairs-gk-bank', 'Science & Technology', 4, 57, 'What is the SI unit of power, and after whom is it named?', 'The **SI unit of power** is the **Watt (W)**, named after Scottish engineer **James Watt**.

One Watt is equivalent to **one joule of energy transferred per second**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00346', 'current-affairs-gk-bank', 'Science & Technology', 4, 58, 'What is the SI unit of energy or work, and after whom is it named?', 'The **SI unit of energy (or work)** is the **Joule (J)**, named after English physicist **James Prescott Joule**.

It is defined as the energy transferred when a force of **one Newton moves an object one metre**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00347', 'current-affairs-gk-bank', 'Science & Technology', 4, 59, 'What is the SI unit of pressure, and after whom is it named?', 'The **SI unit of pressure** is the **Pascal (Pa)**, named after French scientist **Blaise Pascal**.

One Pascal is defined as **one Newton of force applied over an area of one square metre**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00348', 'current-affairs-gk-bank', 'Science & Technology', 4, 60, 'What is the SI unit of frequency, and after whom is it named?', 'The **SI unit of frequency** is the **Hertz (Hz)**, named after German physicist **Heinrich Hertz**.

It measures the number of **cycles or oscillations occurring per second**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00349', 'current-affairs-gk-bank', 'Science & Technology', 4, 61, 'Who discovered the electron, and when?', '**J. J. Thomson**, a British physicist, discovered the **electron in 1897**, through his experiments with cathode ray tubes.

This discovery disproved the earlier idea of the atom as an **indivisible particle**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00350', 'current-affairs-gk-bank', 'Science & Technology', 4, 62, 'Who proposed the nuclear model of the atom, with a dense central nucleus?', '**Ernest Rutherford** proposed the **nuclear model of the atom in 1911**, based on his famous **gold foil experiment**.

His model described the atom as having a **small, dense, positively charged nucleus** surrounded by orbiting electrons.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00351', 'current-affairs-gk-bank', 'Science & Technology', 4, 63, 'What is significant about the discovery of the Higgs boson?', 'The **Higgs boson**, often called the **"God particle,"** was confirmed experimentally in **2012** at CERN''s Large Hadron Collider.

It helps explain how **fundamental particles acquire mass**, confirming a key prediction of the **Standard Model of particle physics**, theorised decades earlier by Peter Higgs and others.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00352', 'current-affairs-gk-bank', 'Science & Technology', 4, 64, 'What was significant about Aryabhata''s contributions to mathematics and astronomy?', 'The ancient Indian mathematician-astronomer **Aryabhata (476-550 CE)** is credited with important contributions, including an **early formulation of the concept of zero''s place value** and calculations of **pi (π)** to a close approximation.

He also proposed that the **Earth rotates on its axis**, a remarkably advanced idea for his time.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00353', 'current-affairs-gk-bank', 'Science & Technology', 4, 65, 'Who is credited with the ancient Indian concept of "zero" as a number?', 'The mathematician **Brahmagupta (598-668 CE)** is widely credited with providing the **first formal rules for arithmetic involving zero** as a number in his work *"Brahmasphutasiddhanta."*

This conceptual advance was crucial to the later development of mathematics worldwide.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00354', 'current-affairs-gk-bank', 'Science & Technology', 4, 66, 'What is the significance of Srinivasa Ramanujan in the history of mathematics?', '**Srinivasa Ramanujan** was a self-taught Indian mathematician who made substantial contributions to **number theory, infinite series, and continued fractions**, mostly in the early 20th century.

Despite having little formal training, he collaborated with British mathematician **G. H. Hardy** at Cambridge, producing work still studied today.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00355', 'current-affairs-gk-bank', 'Science & Technology', 4, 67, 'What was significant about the invention of the transistor?', 'The **transistor** was invented in **1947** at **Bell Labs** in the United States, by scientists **John Bardeen, Walter Brattain, and William Shockley**.

It replaced bulkier vacuum tubes and is considered the **foundational building block of modern electronics**, earning its inventors the 1956 Nobel Prize in Physics.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00356', 'current-affairs-gk-bank', 'Science & Technology', 4, 68, 'What was ENIAC, and why is it significant in computing history?', '**ENIAC (Electronic Numerical Integrator and Computer)**, completed in **1945** in the United States, is widely regarded as one of the **earliest general-purpose electronic digital computers**.

It used thousands of vacuum tubes and was originally developed to calculate artillery firing tables.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00357', 'current-affairs-gk-bank', 'Science & Technology', 4, 69, 'Which Indian scientist is associated with the discovery of the "Bose-Einstein statistics" in physics?', '**Satyendra Nath Bose**, an Indian physicist, collaborated with **Albert Einstein** to develop what became known as **"Bose-Einstein statistics"** in the 1920s.

The subatomic particle class **"boson"** is named in his honour.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00358', 'current-affairs-gk-bank', 'Science & Technology', 4, 70, 'What is the significance of Jagadish Chandra Bose''s scientific work?', '**Jagadish Chandra Bose** was a pioneering Indian scientist known for his research on **radio waves and microwave optics**, as well as his studies showing that **plants exhibit responses to external stimuli**.

He is considered one of the **fathers of radio science**, having conducted some of the earliest experiments in wireless signal transmission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00359', 'current-affairs-gk-bank', 'Economy & Business', 5, 0, 'When was the Reserve Bank of India (RBI) established, and where is it headquartered?', 'The **Reserve Bank of India (RBI)** was established on **1 April 1935**, under the **Reserve Bank of India Act, 1934**.

It is headquartered in **Mumbai** and serves as **India''s central bank**, responsible for monetary policy and currency regulation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00360', 'current-affairs-gk-bank', 'Economy & Business', 5, 1, 'When was the Reserve Bank of India nationalised?', 'The **Reserve Bank of India** was **nationalised on 1 January 1949**, bringing it fully under government ownership.

It had originally been established in **1935** as a shareholder-owned institution before nationalisation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00361', 'current-affairs-gk-bank', 'Economy & Business', 5, 2, 'What is SEBI, and when was it established?', '**SEBI (Securities and Exchange Board of India)** is India''s **capital markets regulator**.

It was established in **1988** and was given **statutory powers in 1992**, through the SEBI Act, to regulate stock exchanges and protect investors.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00362', 'current-affairs-gk-bank', 'Economy & Business', 5, 3, 'What is the Bombay Stock Exchange (BSE), and why is it historically significant?', 'The **Bombay Stock Exchange (BSE)**, established in **1875**, is the **oldest stock exchange in Asia**.

It is one of India''s two major stock exchanges and is home to the benchmark index known as the **"Sensex."**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00363', 'current-affairs-gk-bank', 'Economy & Business', 5, 4, 'When was the National Stock Exchange (NSE) established?', 'The **National Stock Exchange (NSE)** was established in **1992** and began operations in **1994**.

It introduced **electronic, screen-based trading** to India and is home to the benchmark index known as the **"Nifty 50."**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00364', 'current-affairs-gk-bank', 'Economy & Business', 5, 5, 'What is the Sensex, and how many companies does it track?', 'The **Sensex (BSE Sensitive Index)** is the benchmark stock market index of the **Bombay Stock Exchange**.

It tracks the performance of **30 of the largest and most actively traded companies** listed on the BSE.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00365', 'current-affairs-gk-bank', 'Economy & Business', 5, 6, 'What is the Nifty 50, and which exchange does it belong to?', 'The **Nifty 50** is the benchmark stock market index of the **National Stock Exchange (NSE)**.

It tracks the weighted performance of **50 of the largest companies** listed on the NSE across various sectors.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00366', 'current-affairs-gk-bank', 'Economy & Business', 5, 7, 'Which organisation regulates the insurance sector in India?', 'The **Insurance Regulatory and Development Authority of India (IRDAI)** regulates and promotes the **insurance industry** in India.

It was established in **1999**, following the recommendations of the **Malhotra Committee**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00367', 'current-affairs-gk-bank', 'Economy & Business', 5, 8, 'Which organisation regulates pension funds in India?', 'The **Pension Fund Regulatory and Development Authority (PFRDA)** regulates **pension funds**, including the National Pension System, in India.

It was established in **2003**, and received statutory status through an Act of Parliament in **2013**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00368', 'current-affairs-gk-bank', 'Economy & Business', 5, 9, 'What is NABARD, and when was it established?', '**NABARD (National Bank for Agriculture and Rural Development)** was established in **1982**.

It serves as the **apex development bank** responsible for financing and regulating institutions involved in agriculture and rural development in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00369', 'current-affairs-gk-bank', 'Economy & Business', 5, 10, 'What is SIDBI, and what is its focus?', '**SIDBI (Small Industries Development Bank of India)** was established in **1990**.

It is the **principal financial institution** for promoting, financing, and developing **micro, small, and medium enterprises (MSMEs)** in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00370', 'current-affairs-gk-bank', 'Economy & Business', 5, 11, 'What is the Export-Import Bank of India (EXIM Bank)?', 'The **Export-Import Bank of India (EXIM Bank)** was established in **1982**.

It provides **financial assistance to exporters and importers**, and promotes India''s international trade.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00371', 'current-affairs-gk-bank', 'Economy & Business', 5, 12, 'Which Indian bank is considered to have the oldest banking lineage, tracing back to colonial times?', 'The **State Bank of India (SBI)** traces its origins to the **Bank of Calcutta, founded in 1806**, which later became the **Imperial Bank of India**.

SBI was formed in its current name in **1955**, after the nationalisation of the Imperial Bank of India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00372', 'current-affairs-gk-bank', 'Economy & Business', 5, 13, 'Which was the first bank in India to be founded entirely by Indians?', '**Punjab National Bank**, founded in **1894**, is recognised as the **first bank established entirely with Indian capital and management**.

It remains one of India''s largest public sector banks today.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00373', 'current-affairs-gk-bank', 'Economy & Business', 5, 14, 'When were Indian banks first nationalised, and how many banks were involved?', 'A major wave of **bank nationalisation** occurred in **1969**, when the Indian government nationalised **14 major private banks**.

A **second round of nationalisation in 1980** brought **6 more banks** under government control.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00374', 'current-affairs-gk-bank', 'Economy & Business', 5, 15, 'When was India''s first paper currency issued?', 'India''s **first paper currency** was issued by the British colonial government under the **Paper Currency Act of 1861**.

Prior to this, various princely states and private banks had issued their own currency notes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00375', 'current-affairs-gk-bank', 'Economy & Business', 5, 16, 'Which authority is responsible for issuing currency notes in India today?', 'The **Reserve Bank of India (RBI)** is the sole authority responsible for the **issue of currency notes** in India, under the RBI Act, 1934.

**Coins**, however, are minted by the **Government of India** and circulated through the RBI.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00376', 'current-affairs-gk-bank', 'Economy & Business', 5, 17, 'What does GDP stand for, and what does it measure?', '**GDP** stands for **"Gross Domestic Product."**

It measures the **total monetary value of all final goods and services produced within a country''s borders** over a specific period, typically a year or a quarter.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00377', 'current-affairs-gk-bank', 'Economy & Business', 5, 18, 'What is the key difference between GDP and GNP?', '**GDP (Gross Domestic Product)** measures output produced **within a country''s borders**, regardless of who produces it.

**GNP (Gross National Product)** measures output produced by a **country''s residents and companies**, regardless of where in the world it is produced.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00378', 'current-affairs-gk-bank', 'Economy & Business', 5, 19, 'What is NITI Aayog, and what did it replace?', '**NITI Aayog (National Institution for Transforming India)** was established in **2015**, replacing the **Planning Commission**, which had existed since **1950**.

It serves as the government''s premier **policy think tank**, guiding development strategy without the fund-allocation powers its predecessor held.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00379', 'current-affairs-gk-bank', 'Economy & Business', 5, 20, 'When was India''s first Five-Year Plan launched?', 'India''s **first Five-Year Plan** was launched in **1951**, under the **Planning Commission**, focusing primarily on **agriculture and irrigation**.

The Five-Year Plan system was eventually discontinued after the **12th Plan (2012-2017)**, following the creation of **NITI Aayog**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00380', 'current-affairs-gk-bank', 'Economy & Business', 5, 21, 'What is the International Monetary Fund (IMF), and when was it established?', 'The **International Monetary Fund (IMF)** was established in **1944** at the **Bretton Woods Conference**.

It is headquartered in **Washington, D.C.**, and works to ensure **global monetary cooperation and financial stability**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00381', 'current-affairs-gk-bank', 'Economy & Business', 5, 22, 'When was the World Bank established, and where is it headquartered?', 'The **World Bank** was established in **1944**, alongside the IMF, at the **Bretton Woods Conference**.

It is headquartered in **Washington, D.C.**, and provides loans and grants to developing countries for development projects.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00382', 'current-affairs-gk-bank', 'Economy & Business', 5, 23, 'What is the World Trade Organization (WTO), and what did it replace?', 'The **World Trade Organization (WTO)** was established in **1995**, replacing the earlier **General Agreement on Tariffs and Trade (GATT)**, which had existed since **1947**.

It is headquartered in **Geneva, Switzerland**, and regulates international trade rules between member nations.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00383', 'current-affairs-gk-bank', 'Economy & Business', 5, 24, 'In which year did India undertake its major economic liberalisation reforms?', 'India undertook major **economic liberalisation reforms in 1991**, under then Finance Minister **Dr. Manmohan Singh** and Prime Minister **P. V. Narasimha Rao**.

These reforms are often referred to as **"LPG" reforms** — **Liberalisation, Privatisation, and Globalisation**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00384', 'current-affairs-gk-bank', 'Economy & Business', 5, 25, 'What is the Narasimham Committee known for?', 'The **Narasimham Committee**, with reports in **1991 and 1998**, recommended major **banking sector reforms** in India.

Its recommendations shaped reforms related to **non-performing assets, capital adequacy, and the restructuring of public sector banks**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00385', 'current-affairs-gk-bank', 'Economy & Business', 5, 26, 'What is the "repo rate" in monetary policy?', 'The **repo rate** is the rate at which the **Reserve Bank of India lends short-term funds to commercial banks**, against government securities as collateral.

It is one of RBI''s primary tools for **controlling inflation and liquidity** in the economy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00386', 'current-affairs-gk-bank', 'Economy & Business', 5, 27, 'What is the "reverse repo rate"?', 'The **reverse repo rate** is the rate at which the **Reserve Bank of India borrows funds from commercial banks**, effectively absorbing excess liquidity from the banking system.

It works in tandem with the repo rate as a key monetary policy tool.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00387', 'current-affairs-gk-bank', 'Economy & Business', 5, 28, 'What is the Cash Reserve Ratio (CRR)?', 'The **Cash Reserve Ratio (CRR)** is the **minimum percentage of a bank''s total deposits** that it must maintain as reserves with the **Reserve Bank of India**, in cash form.

It is a tool used by the RBI to regulate the **money supply and liquidity** in the banking system.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00388', 'current-affairs-gk-bank', 'Economy & Business', 5, 29, 'What is the Statutory Liquidity Ratio (SLR)?', 'The **Statutory Liquidity Ratio (SLR)** is the **minimum percentage of a bank''s net demand and time liabilities** that it must maintain in the form of liquid assets, such as cash, gold, or approved government securities.

It is regulated by the **Reserve Bank of India** to ensure the solvency of banks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00389', 'current-affairs-gk-bank', 'Economy & Business', 5, 30, 'What does the term "inflation" mean in economics?', '**Inflation** refers to a **sustained general increase in the price level** of goods and services in an economy over time.

It results in a **decrease in the purchasing power** of a currency, and is commonly measured using indices such as the **Consumer Price Index (CPI)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00390', 'current-affairs-gk-bank', 'Economy & Business', 5, 31, 'What does the term "fiscal deficit" mean?', 'A **fiscal deficit** occurs when a government''s **total expenditure exceeds its total revenue** (excluding borrowings) in a given financial year.

It indicates the extent to which the government needs to **borrow funds** to meet its spending commitments.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00391', 'current-affairs-gk-bank', 'Economy & Business', 5, 32, 'What is a "basis point" in financial terminology?', 'A **"basis point"** is a unit of measurement equal to **one-hundredth of one percentage point (0.01%)**.

It is commonly used to describe changes in **interest rates or yields**, where, for example, a move from 6.00% to 6.25% is referred to as a **25 basis-point increase**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00392', 'current-affairs-gk-bank', 'Economy & Business', 5, 33, 'What does "SDR" stand for in the context of the IMF?', '**"SDR"** stands for **"Special Drawing Rights,"** an international reserve asset created by the **IMF in 1969**.

Its value is based on a **basket of major global currencies**, and it supplements member countries'' official reserves.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00393', 'current-affairs-gk-bank', 'Economy & Business', 5, 34, 'What does the acronym BRICS stand for, and how did the grouping originate?', '**BRICS** stands for **Brazil, Russia, India, China, and South Africa**.

The term **"BRIC"** was first coined by economist **Jim O''Neill in 2001**; **South Africa joined in 2010**, forming the current BRICS grouping.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00394', 'current-affairs-gk-bank', 'Economy & Business', 5, 35, 'What is the New Development Bank (NDB)?', 'The **New Development Bank (NDB)**, often called the **"BRICS Bank,"** was established in **2014** by the BRICS nations.

It is headquartered in **Shanghai, China**, and finances infrastructure and sustainable development projects in member and other emerging economies.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00395', 'current-affairs-gk-bank', 'Economy & Business', 5, 36, 'What is the Asian Infrastructure Investment Bank (AIIB)?', 'The **Asian Infrastructure Investment Bank (AIIB)** was established in **2016**, headquartered in **Beijing, China**.

It is a **multilateral development bank** focused on financing infrastructure projects across Asia, and was initiated primarily by China.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00396', 'current-affairs-gk-bank', 'Economy & Business', 5, 37, 'What is the Asian Development Bank (ADB)?', 'The **Asian Development Bank (ADB)** was established in **1966**, headquartered in **Manila, Philippines**.

It works to promote **economic and social development** across the Asia-Pacific region through loans, grants, and technical assistance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00397', 'current-affairs-gk-bank', 'Economy & Business', 5, 38, 'What was "demonetisation" in India, and when did it occur?', '**Demonetisation** in India occurred on **8 November 2016**, when the government withdrew the legal tender status of **₹500 and ₹1,000 banknotes**.

The stated objectives included curbing **black money, counterfeit currency, and corruption**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00398', 'current-affairs-gk-bank', 'Economy & Business', 5, 39, 'What is the GST Council, and how was it constituted?', 'The **GST Council** was constituted following the **101st Constitutional Amendment Act, 2016**, which paved the way for the Goods and Services Tax.

It is **chaired by the Union Finance Minister** and includes finance ministers of all states, responsible for deciding GST rates and rules.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00399', 'current-affairs-gk-bank', 'Economy & Business', 5, 40, 'What is an Initial Public Offering (IPO)?', 'An **Initial Public Offering (IPO)** is the process through which a **private company offers its shares to the public for the first time**, becoming a publicly listed company.

It is typically used by companies to **raise capital** for expansion or other business needs.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00400', 'current-affairs-gk-bank', 'Economy & Business', 5, 41, 'What is the difference between FDI and FPI?', '**FDI (Foreign Direct Investment)** involves a foreign entity acquiring a **lasting, controlling interest** in a business, often through setting up operations or acquiring significant equity.

**FPI (Foreign Portfolio Investment)** refers to investment in **financial assets like stocks and bonds**, without seeking control over the underlying business.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00401', 'current-affairs-gk-bank', 'Economy & Business', 5, 42, 'What does the "Balance of Payments" record?', 'The **Balance of Payments (BoP)** is a systematic record of a **country''s economic transactions with the rest of the world** over a given period.

It comprises the **current account** (trade in goods/services, income, transfers) and the **capital account** (capital transfers and asset transactions).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00402', 'current-affairs-gk-bank', 'Economy & Business', 5, 43, 'What is the Federation of Indian Chambers of Commerce and Industry (FICCI)?', '**FICCI**, founded in **1927**, is one of India''s **oldest and largest apex business organisations**.

It represents the interests of Indian businesses across sectors and advocates on policy matters affecting trade and industry.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00403', 'current-affairs-gk-bank', 'Economy & Business', 5, 44, 'What is the Confederation of Indian Industry (CII)?', 'The **Confederation of Indian Industry (CII)** traces its origins to **1895**, when it was founded as the **Engineering and Iron Trades Association**, later being renamed CII in **1992**.

It is a prominent **industry association** representing Indian businesses on policy and economic issues.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00404', 'current-affairs-gk-bank', 'Economy & Business', 5, 45, 'What does the term "unicorn" mean in the startup ecosystem?', 'A **"unicorn"** refers to a **privately held startup company valued at over US$1 billion**.

The term was coined by venture capitalist **Aileen Lee in 2013**, referencing the rarity of such high-value startups at the time.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00405', 'current-affairs-gk-bank', 'Economy & Business', 5, 46, 'When was the East India Company founded, and under what authority?', 'The **English East India Company** was founded in **1600**, under a **royal charter granted by Queen Elizabeth I**.

It eventually evolved from a trading company into a major **political and administrative power in India**, before the British Crown took direct control in 1858.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00406', 'current-affairs-gk-bank', 'Economy & Business', 5, 47, 'What was the economic context of the Swadeshi Movement?', 'The **Swadeshi Movement**, launched in **1905** in response to the **Partition of Bengal**, called for the **boycott of British goods** and the promotion of **indigenously made (swadeshi) products**.

It marked an early link between India''s nationalist movement and economic self-reliance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00407', 'current-affairs-gk-bank', 'Economy & Business', 5, 48, 'What is a "demat account"?', 'A **"demat (dematerialised) account"** is an account that holds an investor''s **shares and securities in electronic form**, rather than as physical certificates.

It simplifies the process of trading, transferring, and holding securities in the stock market.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00408', 'current-affairs-gk-bank', 'Economy & Business', 5, 49, 'Which was India''s first securities depository, and when was it established?', '**NSDL (National Securities Depository Limited)**, established in **1996**, was **India''s first securities depository**.

It was followed by **CDSL (Central Depository Services Limited)**, established in **1999**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00409', 'current-affairs-gk-bank', 'Economy & Business', 5, 50, 'What does "blue chip" mean in stock market terminology?', 'A **"blue chip"** stock refers to shares of a **large, financially stable, and well-established company** with a reliable history of performance.

The term is derived from **poker**, where blue chips traditionally carry the **highest value**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00410', 'current-affairs-gk-bank', 'Economy & Business', 5, 51, 'What do the terms "bull market" and "bear market" mean?', 'A **"bull market"** refers to a period when **stock prices are generally rising**, reflecting investor optimism.

A **"bear market"** refers to a period when **stock prices are generally falling**, reflecting investor pessimism.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00411', 'current-affairs-gk-bank', 'Economy & Business', 5, 52, 'What is a mutual fund, and who regulates mutual funds in India?', 'A **mutual fund** pools money from multiple investors to invest collectively in **stocks, bonds, or other securities**, managed by professional fund managers.

In India, mutual funds are regulated by **SEBI (Securities and Exchange Board of India)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00412', 'current-affairs-gk-bank', 'Economy & Business', 5, 53, 'What is AMFI, and what role does it play?', '**AMFI (Association of Mutual Funds in India)**, established in **1995**, is the **industry body representing mutual fund companies** in India.

It works to promote **investor awareness and ethical standards** within the mutual fund industry, under the regulatory oversight of SEBI.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00413', 'current-affairs-gk-bank', 'Economy & Business', 5, 54, 'What is a credit rating agency, and which was India''s first?', 'A **credit rating agency** assesses the **creditworthiness of borrowers**, including companies and governments, assigning ratings that reflect default risk.

**CRISIL**, established in **1987**, was **India''s first credit rating agency**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00414', 'current-affairs-gk-bank', 'Economy & Business', 5, 55, 'What is the Companies Act, 2013, and which ministry administers it?', 'The **Companies Act, 2013** is the principal legislation governing the **incorporation, governance, and regulation of companies** in India.

It is administered by the **Ministry of Corporate Affairs (MCA)**, and replaced the earlier Companies Act of 1956.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00415', 'current-affairs-gk-bank', 'Economy & Business', 5, 56, 'What does "disinvestment" mean in the context of government policy?', '**Disinvestment** refers to the **sale or liquidation of the government''s stake** in public sector undertakings (PSUs).

It is typically undertaken to **raise revenue, improve efficiency, or reduce the fiscal deficit**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00416', 'current-affairs-gk-bank', 'Economy & Business', 5, 57, 'What is the significance of the 1991 Balance of Payments crisis in Indian economic history?', 'In **1991**, India faced a severe **Balance of Payments crisis**, with foreign exchange reserves falling to levels barely sufficient to cover a few weeks of imports.

This crisis directly triggered the **economic liberalisation reforms of 1991**, reshaping India''s economic policy framework.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00417', 'current-affairs-gk-bank', 'Economy & Business', 5, 58, 'What is a "Non-Performing Asset (NPA)" in banking?', 'A **"Non-Performing Asset (NPA)"** refers to a **loan or advance for which the principal or interest payment has remained overdue for a specified period** (typically 90 days in India).

A high level of NPAs indicates stress in a bank''s loan portfolio and overall asset quality.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00418', 'current-affairs-gk-bank', 'Economy & Business', 5, 59, 'What is the role of the Competition Commission of India (CCI)?', 'The **Competition Commission of India (CCI)** was established under the **Competition Act, 2002**, and became fully operational in **2009**.

It aims to **prevent practices that adversely affect competition**, promote fair business practices, and protect consumer interests in markets.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00419', 'current-affairs-gk-bank', 'Economy & Business', 5, 60, 'What is the significance of the term "Angel Investor" in startup financing?', 'An **"angel investor"** is typically a **wealthy individual who provides early-stage capital** to startups, often in exchange for equity or convertible debt.

Angel investment usually occurs at an **earlier stage** than venture capital funding.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00420', 'current-affairs-gk-bank', 'Economy & Business', 5, 61, 'What does "venture capital" refer to in business financing?', '**Venture capital (VC)** refers to **financing provided to early-stage, high-growth-potential startups**, typically by specialised investment firms, in exchange for equity ownership.

It generally involves **higher risk** in exchange for the potential of significant returns if the business succeeds.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00421', 'current-affairs-gk-bank', 'Economy & Business', 5, 62, 'What is the significance of the Minimum Support Price (MSP) in Indian agriculture?', 'The **Minimum Support Price (MSP)** is a **price floor set by the government** for certain agricultural commodities, to protect farmers from sharp price falls.

It is announced on the recommendation of the **Commission for Agricultural Costs and Prices (CACP)**, established in **1965**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00422', 'current-affairs-gk-bank', 'Economy & Business', 5, 63, 'What was the Gold Standard, and why did most countries abandon it?', 'The **Gold Standard** was a monetary system in which a country''s currency value was **directly linked to a fixed quantity of gold**.

Most major economies, including the United States, **abandoned the Gold Standard by the early 1970s**, moving to systems of floating exchange rates instead.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00423', 'current-affairs-gk-bank', 'Economy & Business', 5, 64, 'What is the Bretton Woods Conference known for?', 'The **Bretton Woods Conference**, held in **1944** in the United States, led to the creation of the **International Monetary Fund (IMF) and the World Bank**.

It also established a system of **fixed exchange rates** pegged to the US dollar, which itself was convertible to gold.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00424', 'current-affairs-gk-bank', 'Economy & Business', 5, 65, 'What does the term "capital gains tax" refer to?', '**Capital gains tax** is a tax levied on the **profit earned from the sale of a capital asset**, such as property, stocks, or bonds.

It is generally classified into **short-term and long-term capital gains**, based on the holding period of the asset.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00425', 'current-affairs-gk-bank', 'Economy & Business', 5, 66, 'What is the significance of the term "direct tax" versus "indirect tax"?', 'A **"direct tax,"** such as income tax, is paid **directly by the individual or entity** on whom it is levied, and its burden cannot be shifted.

An **"indirect tax,"** such as GST, is levied on **goods and services** and can be passed on from the seller to the final consumer.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00426', 'current-affairs-gk-bank', 'Economy & Business', 5, 67, 'What is the Public Distribution System (PDS) in India?', 'The **Public Distribution System (PDS)** is a government-managed system for distributing **subsidised food grains and essential commodities** to the population through a network of **"Fair Price Shops."**

It forms the backbone of India''s food security framework, alongside laws such as the National Food Security Act.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00427', 'current-affairs-gk-bank', 'Economy & Business', 5, 68, 'What is the significance of the term "Special Economic Zone (SEZ)"?', 'A **Special Economic Zone (SEZ)** is a designated area within a country that offers **distinct economic regulations and incentives**, such as tax benefits, to attract investment and boost exports.

India''s SEZ policy was formalised under the **Special Economic Zones Act, 2005**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00428', 'current-affairs-gk-bank', 'Economy & Business', 5, 69, 'What is meant by the term "Licence Raj" in Indian economic history?', '**"Licence Raj"** refers to the system of **extensive government licensing, regulations, and red tape** that governed private businesses in India, particularly between the 1950s and 1991.

It was substantially dismantled following the **economic liberalisation reforms of 1991**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00429', 'current-affairs-gk-bank', 'Economy & Business', 5, 70, 'What is the role of the Employees'' State Insurance Corporation (ESIC)?', 'The **Employees'' State Insurance Corporation (ESIC)** was established under the **Employees'' State Insurance Act, 1948**.

It provides **medical, sickness, maternity, and disability benefits** to workers in the organised sector, funded through contributions from employers and employees.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00430', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 0, 'When was the United Nations (UN) founded, and where is it headquartered?', 'The **United Nations (UN)** was founded in **1945**, with its **Charter signed in San Francisco** by **51 founding member countries**.

It is headquartered in **New York City**, United States.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00431', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 1, 'What is the composition of the UN Security Council?', 'The **UN Security Council** consists of **5 permanent members** — the **United States, United Kingdom, France, Russia, and China** — and **10 non-permanent members**, elected for **two-year terms**.

The permanent members hold **veto power** over substantive Security Council resolutions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00432', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 2, 'When is United Nations Day observed, and why that date?', '**United Nations Day** is observed annually on **24 October**.

The date marks the anniversary of the **UN Charter coming into force in 1945**, after being ratified by a majority of its signatories.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00433', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 3, 'What are the six official languages of the United Nations?', 'The **six official languages of the United Nations** are **Arabic, Chinese, English, French, Russian, and Spanish**.

These languages are used across official UN documentation and proceedings.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00434', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 4, 'Who was the first Secretary-General of the United Nations?', '**Trygve Lie**, a Norwegian diplomat, served as the **first Secretary-General of the United Nations**, from **1946 to 1952**.

The Secretary-General acts as the chief administrative officer of the organisation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00435', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 5, 'What was the League of Nations, and why is it historically significant?', 'The **League of Nations** was an international organisation founded in **1920**, following the **First World War**, headquartered in **Geneva**.

It is considered the **forerunner of the United Nations**, and was formally dissolved in **1946** after failing to prevent the Second World War.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00436', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 6, 'Who proposed the establishment of the League of Nations?', 'The **League of Nations** was proposed primarily by U.S. President **Woodrow Wilson**, as part of his **"Fourteen Points"** peace programme after the First World War.

Notably, the **United States itself never joined** the League, as the US Senate did not ratify the relevant treaty.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00437', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 7, 'What is UNESCO, and when was it established?', '**UNESCO (United Nations Educational, Scientific and Cultural Organization)** was established in **1945**, headquartered in **Paris, France**.

It works to promote **international cooperation in education, science, culture, and communication**, and is well known for designating World Heritage Sites.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00438', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 8, 'What is the World Health Organization (WHO), and when was it founded?', 'The **World Health Organization (WHO)** was founded in **1948**, headquartered in **Geneva, Switzerland**.

It is the **UN''s specialised agency for international public health**, working to coordinate global responses to health challenges.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00439', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 9, 'What is UNICEF, and when was it established?', '**UNICEF (United Nations Children''s Fund)** was established in **1946**, headquartered in **New York**.

It works globally to protect the **rights and welfare of children**, providing humanitarian and developmental assistance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00440', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 10, 'What is the International Labour Organization (ILO), and why is it historically notable?', 'The **International Labour Organization (ILO)** was founded in **1919**, making it the **oldest specialised agency associated with the UN** (predating the UN itself).

Headquartered in **Geneva**, it works to set international **labour standards** and was awarded the **Nobel Peace Prize in 1969**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00441', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 11, 'What is UNHCR, and what is its mandate?', '**UNHCR (the UN High Commissioner for Refugees)** was established in **1950**, headquartered in **Geneva, Switzerland**.

Its mandate is to **protect refugees, displaced persons, and stateless people**, and to help find solutions to displacement crises worldwide.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00442', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 12, 'What is the International Atomic Energy Agency (IAEA)?', 'The **International Atomic Energy Agency (IAEA)** was established in **1957**, headquartered in **Vienna, Austria**.

It works to promote the **peaceful use of nuclear energy** while helping prevent its use for military purposes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00443', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 13, 'What is NATO, and when was it founded?', '**NATO (North Atlantic Treaty Organization)** was founded in **1949**, headquartered in **Brussels, Belgium**.

It is a **military and political alliance** originally formed by Western countries as a collective defence pact during the Cold War.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00444', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 14, 'What was the Warsaw Pact, and how did it relate to NATO?', 'The **Warsaw Pact** was a **collective defence alliance formed in 1955** among the Soviet Union and its Eastern European allies, serving as the **Soviet-led counterpart to NATO**.

It was **dissolved in 1991**, following the end of the Cold War and the collapse of the Soviet bloc.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00445', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 15, 'What is ASEAN, and when was it founded?', '**ASEAN (Association of Southeast Asian Nations)** was founded in **1967**, headquartered in **Jakarta, Indonesia**.

It promotes **economic, political, and security cooperation** among Southeast Asian nations.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00446', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 16, 'What is SAARC, and which countries are its members?', '**SAARC (South Asian Association for Regional Cooperation)** was founded in **1985**, headquartered in **Kathmandu, Nepal**.

Its eight members are **Afghanistan, Bangladesh, Bhutan, India, the Maldives, Nepal, Pakistan, and Sri Lanka**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00447', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 17, 'What is BIMSTEC?', '**BIMSTEC (Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation)** was founded in **1997**, headquartered in **Dhaka, Bangladesh**.

It brings together countries from **South Asia and Southeast Asia** bordering the Bay of Bengal for regional cooperation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00448', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 18, 'What treaty led to the formation of the European Union, and when?', 'The **Maastricht Treaty**, signed in **1992** and effective from **1993**, formally established the **European Union**.

It built upon the earlier **European Economic Community (EEC)**, founded in **1957** under the Treaty of Rome.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00449', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 19, 'What is OPEC, and when was it founded?', '**OPEC (Organization of the Petroleum Exporting Countries)** was founded in **1960**, headquartered in **Vienna, Austria**.

It coordinates petroleum policy among its member nations to **stabilise oil markets** and secure fair prices for producers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00450', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 20, 'What is the modern Commonwealth of Nations, and how did it originate?', 'The **modern Commonwealth of Nations** traces its formal origin to the **London Declaration of 1949**.

It is a voluntary association of mostly former territories of the **British Empire**, with its secretariat headquartered in **London**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00451', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 21, 'What is Interpol, and when was it founded?', '**Interpol (International Criminal Police Organization)** was founded in **1923**, headquartered in **Lyon, France**.

It facilitates **international police cooperation** to combat cross-border crime.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00452', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 22, 'Who founded the International Committee of the Red Cross, and when?', 'The **International Committee of the Red Cross (ICRC)** was founded in **1863** by Swiss businessman **Henry Dunant**, headquartered in **Geneva, Switzerland**.

Dunant was later awarded the **first-ever Nobel Peace Prize in 1901** for this humanitarian initiative.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00453', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 23, 'What is the International Court of Justice (ICJ)?', 'The **International Court of Justice (ICJ)** is the **principal judicial organ of the United Nations**, established in **1945** and headquartered at **The Hague, Netherlands**.

It settles **legal disputes between states** and gives advisory opinions on international legal questions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00454', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 24, 'What is the International Criminal Court (ICC), and how does it differ from the ICJ?', 'The **International Criminal Court (ICC)** was established by the **Rome Statute in 1998**, coming into force in **2002**, and is also headquartered at **The Hague**.

Unlike the ICJ, which settles disputes **between states**, the ICC prosecutes **individuals** for crimes such as genocide, war crimes, and crimes against humanity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00455', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 25, 'What is the Shanghai Cooperation Organisation (SCO)?', 'The **Shanghai Cooperation Organisation (SCO)** was founded in **2001**, headquartered in **Beijing, China**.

It is a **Eurasian political, economic, and security alliance**, evolving from the earlier "Shanghai Five" grouping formed in 1996.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00456', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 26, 'What is the Food and Agriculture Organization (FAO)?', 'The **Food and Agriculture Organization (FAO)** was founded in **1945**, headquartered in **Rome, Italy**.

It is the **UN''s specialised agency for food security and agriculture**, working to eliminate hunger and improve nutrition worldwide.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00457', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 27, 'What is the World Intellectual Property Organization (WIPO)?', 'The **World Intellectual Property Organization (WIPO)** was founded in **1967**, headquartered in **Geneva, Switzerland**.

It is the **UN''s specialised agency for promoting intellectual property protection** worldwide, including patents, trademarks, and copyrights.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00458', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 28, 'What is the International Civil Aviation Organization (ICAO)?', 'The **International Civil Aviation Organization (ICAO)** was established in **1944** through the **Chicago Convention**, headquartered in **Montreal, Canada**.

It sets global standards for the **safety, security, and efficiency of international civil aviation**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00459', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 29, 'What is the Universal Postal Union (UPU), and why is it historically notable?', 'The **Universal Postal Union (UPU)** was founded in **1874**, headquartered in **Bern, Switzerland**.

It is one of the **oldest international organisations** still in existence, coordinating postal policies among member countries.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00460', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 30, 'What is the World Meteorological Organization (WMO)?', 'The **World Meteorological Organization (WMO)** was founded in **1950**, headquartered in **Geneva, Switzerland**.

It is the **UN''s specialised agency for meteorology, climatology, and related geophysical sciences**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00461', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 31, 'What is the International Maritime Organization (IMO)?', 'The **International Maritime Organization (IMO)** was founded in **1948**, headquartered in **London, United Kingdom**.

It is the **UN''s specialised agency responsible for the safety and security of shipping** and the prevention of marine pollution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00462', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 32, 'What is the International Telecommunication Union (ITU), and why is it historically significant?', 'The **International Telecommunication Union (ITU)**, founded in **1865** as the **International Telegraph Union**, is considered the **oldest intergovernmental organisation** still in existence.

Headquartered in **Geneva, Switzerland**, it is now the UN''s specialised agency for **information and communication technologies**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00463', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 33, 'Where is the headquarters of the UN Environment Programme (UNEP)?', 'The **UN Environment Programme (UNEP)** was established in **1972**, headquartered in **Nairobi, Kenya**.

It is notable for being the **only major UN body headquartered in a developing country**, and it coordinates the UN''s environmental activities.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00464', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 34, 'What is UNCTAD?', '**UNCTAD (United Nations Conference on Trade and Development)** was established in **1964**, headquartered in **Geneva, Switzerland**.

It works to promote the **integration of developing countries into the world economy**, particularly in trade and investment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00465', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 35, 'What is the Non-Aligned Movement (NAM), and when was it founded?', 'The **Non-Aligned Movement (NAM)** was founded in **1961** at the **Belgrade Conference**.

It emerged during the **Cold War** as a forum for countries that did not wish to formally align with either the Western or Soviet bloc, with founding leaders including **Jawaharlal Nehru, Josip Broz Tito, Gamal Abdel Nasser, and Sukarno**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00466', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 36, 'What is the African Union (AU), and what did it replace?', 'The **African Union (AU)** was established in **2002**, headquartered in **Addis Ababa, Ethiopia**.

It replaced the earlier **Organisation of African Unity (OAU)**, which had existed since **1963**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00467', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 37, 'What is the Arab League, and when was it founded?', 'The **League of Arab States (Arab League)** was founded in **1945**, headquartered in **Cairo, Egypt**.

It works to promote **cooperation among Arab states** on political, economic, and cultural matters.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00468', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 38, 'What was the significance of the UN Peacekeeping Forces winning the Nobel Peace Prize?', '**United Nations Peacekeeping Forces** were jointly awarded the **Nobel Peace Prize in 1988**.

This recognised their role in **maintaining peace in conflict zones** around the world since their first deployment in 1948.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00469', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 39, 'What is the Organization for Security and Co-operation in Europe (OSCE)?', 'The **Organization for Security and Co-operation in Europe (OSCE)**, headquartered in **Vienna, Austria**, originated as the **Conference on Security and Co-operation in Europe (CSCE) in 1975**, and was renamed in **1995**.

It is the **world''s largest regional security-oriented intergovernmental organisation**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00470', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 40, 'What institutions make up the "World Bank Group"?', 'The **World Bank Group** comprises five institutions: the **IBRD (International Bank for Reconstruction and Development), IDA (International Development Association), IFC (International Finance Corporation), MIGA (Multilateral Investment Guarantee Agency), and ICSID (International Centre for Settlement of Investment Disputes)**.

Together, they support development financing, private sector investment, and dispute resolution worldwide.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00471', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 41, 'What governs activities in Antarctica, and when did it come into force?', 'Activities in Antarctica are governed by the **Antarctic Treaty System**, signed in **1959** and entering into force in **1961**.

It designates Antarctica as a **zone reserved for peaceful purposes and scientific research**, prohibiting military activity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00472', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 42, 'When was the Euro introduced as a currency?', 'The **Euro** was introduced as an **accounting currency in 1999**, with **physical banknotes and coins entering circulation in 2002**.

It serves as the official currency of the **Eurozone**, a subset of European Union member states.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00473', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 43, 'What led to the formation of Bangladesh, and in which year?', '**Bangladesh** was formed in **1971**, following the **Bangladesh Liberation War**, in which India played a significant military role supporting East Pakistan''s independence movement.

The war concluded with the **surrender of Pakistani forces in Dhaka in December 1971**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00474', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 44, 'What was the significance of the Korean Armistice Agreement?', 'The **Korean Armistice Agreement**, signed in **1953**, ended active fighting in the **Korean War (1950-1953)**.

It established the **Korean Demilitarized Zone (DMZ)**, which continues to separate **North and South Korea** to this day.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00475', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 45, 'What was the Berlin Wall, and when was it built and brought down?', 'The **Berlin Wall** was built in **1961**, dividing **East and West Berlin** during the Cold War.

It stood as a powerful symbol of Cold War division until it was **brought down in 1989**, which paved the way for German reunification in 1990.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00476', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 46, 'In which year was Germany reunified?', '**Germany was reunified in 1990**, following the fall of the **Berlin Wall in 1989**.

This brought together **East Germany (German Democratic Republic)** and **West Germany (Federal Republic of Germany)** into a single sovereign state.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00477', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 47, 'What replaced the Soviet Union after its dissolution in 1991?', 'Following the dissolution of the **Soviet Union in 1991**, many of its former republics formed the **Commonwealth of Independent States (CIS)**, a loose regional organisation.

The dissolution marked the formal **end of the Cold War era**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00478', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 48, 'When was the Suez Canal opened, and what does it connect?', 'The **Suez Canal** opened in **1869**, connecting the **Mediterranean Sea and the Red Sea** through Egypt.

It provides a crucial shortcut for maritime trade between Europe and Asia, avoiding the longer route around Africa.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00479', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 49, 'When was the Panama Canal opened, and what does it connect?', 'The **Panama Canal** opened in **1914**, connecting the **Atlantic and Pacific Oceans** through Panama.

It significantly shortened sea voyages between the two oceans, which previously required sailing around South America.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00480', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 50, 'What strait separates India and Sri Lanka?', 'The **Palk Strait** separates **India and Sri Lanka**, connecting the **Bay of Bengal with the Gulf of Mannar**.

It lies between the Indian state of Tamil Nadu and Sri Lanka''s northern coast.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00481', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 51, 'What was the Treaty of Versailles, and what did it conclude?', 'The **Treaty of Versailles**, signed in **1919**, formally ended the **First World War**.

It imposed significant territorial losses and reparations on **Germany**, and its harsh terms are often cited as a contributing factor to the rise of tensions that led to the **Second World War**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00482', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 52, 'What is the Group of Seven (G7)?', 'The **Group of Seven (G7)** is an informal forum of major advanced economies: **the United States, United Kingdom, France, Germany, Italy, Japan, and Canada**.

It emerged from informal summits that began in the mid-1970s, following the global oil crisis.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00483', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 53, 'What is the G20, and when did it begin as a leaders'' summit?', 'The **G20 (Group of Twenty)** was originally established in **1999** as a forum for **finance ministers and central bank governors**.

It was elevated to a **leaders'' summit level in 2008**, in response to the global financial crisis, and includes both advanced and major emerging economies.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00484', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 54, 'What was the significance of the Chicago Convention of 1944?', 'The **Chicago Convention of 1944** established the framework for international civil aviation cooperation, leading to the creation of the **International Civil Aviation Organization (ICAO)**.

It set out principles governing **airspace, aircraft registration, and air travel safety** that remain foundational today.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00485', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 55, 'What is the significance of the Geneva Conventions?', 'The **Geneva Conventions**, the main treaties being updated and finalised in **1949**, establish international legal standards for **humanitarian treatment in war**, including the protection of wounded soldiers, prisoners of war, and civilians.

They form the **core of modern international humanitarian law**, overseen in part by the International Committee of the Red Cross.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00486', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 56, 'What is the significance of the Kyoto Protocol?', 'The **Kyoto Protocol**, adopted in **1997** and entering into force in **2005**, was an international treaty committing industrialised countries to **reduce greenhouse gas emissions**.

It was a precursor to later climate agreements, including the **Paris Agreement of 2015**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00487', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 57, 'What is the significance of the Paris Agreement of 2015?', 'The **Paris Agreement**, adopted in **2015** under the **UN Framework Convention on Climate Change (UNFCCC)**, is a landmark international treaty on **climate change mitigation**.

Its central goal is to limit global warming to **well below 2°C above pre-industrial levels**, with efforts to limit the increase to 1.5°C.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00488', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 58, 'What is the Non-Proliferation Treaty (NPT)?', 'The **Treaty on the Non-Proliferation of Nuclear Weapons (NPT)**, which entered into force in **1970**, aims to **prevent the spread of nuclear weapons** while promoting peaceful uses of nuclear energy.

Notably, **India has never signed the NPT**, viewing it as discriminatory towards non-nuclear-weapon states.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00489', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 59, 'What is the significance of the Montreal Protocol?', 'The **Montreal Protocol**, signed in **1987**, is an international treaty aimed at **phasing out substances responsible for depleting the ozone layer**, such as chlorofluorocarbons (CFCs).

It is widely regarded as one of the **most successful international environmental agreements** in history.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00490', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 60, 'What was the purpose of the Bretton Woods Conference, held alongside creation of the IMF and World Bank?', 'The **Bretton Woods Conference of 1944** established a new international monetary framework after the Second World War, creating the **IMF and World Bank** and a system of **fixed exchange rates**.

It aimed to promote **global economic stability and cooperation**, preventing the economic conditions that contributed to the war.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00491', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 61, 'What is the significance of the term "veto power" at the UN Security Council?', '**"Veto power"** refers to the ability of any of the **five permanent members of the UN Security Council** to block the adoption of any **substantive resolution**, regardless of the level of international support it has.

This power was built into the UN Charter in **1945** to reflect the geopolitical realities at the time of the UN''s founding.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00492', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 62, 'What is the significance of the Helsinki Accords?', 'The **Helsinki Accords**, signed in **1975**, were a key diplomatic agreement during the Cold War, signed by the United States, Canada, the Soviet Union, and most European states.

They addressed issues of **security, human rights, and cooperation**, and led to the creation of the body that later became the **OSCE**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00493', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 63, 'What is the significance of the Vienna Convention on Diplomatic Relations?', 'The **Vienna Convention on Diplomatic Relations**, adopted in **1961**, codifies the rules governing **diplomatic relations between independent states**.

It establishes principles such as **diplomatic immunity** for embassy staff, forming the basis of modern diplomatic law.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00494', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 64, 'What was the historical significance of the Simla Agreement?', 'The **Simla Agreement**, signed in **1972** between **India and Pakistan**, followed the **1971 war** that led to the creation of Bangladesh.

It established the **Line of Control (LoC)** in Jammu and Kashmir and committed both countries to resolving disputes **bilaterally and peacefully**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00495', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 65, 'What was the significance of the Tashkent Agreement?', 'The **Tashkent Agreement**, signed in **January 1966**, formally ended the **1965 Indo-Pakistani War**.

It was signed by Indian Prime Minister **Lal Bahadur Shastri** and Pakistani President **Ayub Khan**, with the Soviet Union mediating the talks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00496', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 66, 'What is the significance of the Panchsheel Agreement between India and China?', 'The **Panchsheel Agreement**, signed in **1954** between India and China, laid out the **"Five Principles of Peaceful Coexistence."**

These principles include **mutual respect for sovereignty and territorial integrity** and **non-interference in internal affairs**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00497', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 67, 'What does the acronym "OECD" stand for, and what is its purpose?', '**OECD** stands for the **"Organisation for Economic Co-operation and Development,"** founded in **1961**, headquartered in **Paris, France**.

It brings together mostly developed economies to promote **policies improving economic and social well-being** worldwide.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00498', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 68, 'What was the significance of the Camp David Accords?', 'The **Camp David Accords**, signed in **1978**, were a framework for peace negotiated between **Egypt and Israel**, mediated by US President **Jimmy Carter**.

They led directly to the **Egypt-Israel Peace Treaty of 1979**, the first instance of an Arab country formally recognising Israel.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00499', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 69, 'What was the significance of the Yalta Conference?', 'The **Yalta Conference**, held in **February 1945**, brought together the leaders of the **United States, United Kingdom, and Soviet Union** — Roosevelt, Churchill, and Stalin.

It shaped key post-war decisions, including the **reorganisation of Europe** and plans for the **establishment of the United Nations**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q00500', 'current-affairs-gk-bank', 'International Affairs & Organizations', 6, 70, 'What is the significance of the Dayton Agreement?', 'The **Dayton Agreement**, signed in **1995**, brought an end to the **Bosnian War (1992-1995)** in the former Yugoslavia.

It established the political structure of **Bosnia and Herzegovina** as a state comprising two main entities, and was negotiated with significant involvement from the **United States**.', '2026-11-14T06:17:56.365Z');

